import type { Soru } from "../sorular";

export const P05: Soru[] = [
  { id: "p05-001", k: "Doğa", s: "Bilinen en büyük hayvan hangisidir?", d: "Mavi balina", y: ["Afrika fili", "Kaşalot"], a: "Mavi balina 30 metreye yaklaşan boyu ve 150 tonu aşabilen ağırlığıyla, bilinen en büyük hayvan kabul edilir." },
  { id: "p05-002", k: "Doğa", s: "Dev mavi balina esas olarak neyle beslenir?", d: "Kril", y: ["Köpekbalıkları", "Foklar"], a: "Mavi balina, karides benzeri küçük kabuklular olan krilleri ağzındaki balina çubuklarıyla sudan süzerek yer." },
  { id: "p05-003", k: "Doğa", s: "Balinalar nasıl nefes alır?", d: "Yüzeye çıkıp akciğerleriyle", y: ["Solungaçlarıyla", "Derileri yoluyla"], a: "Balinalar memelidir; solungaçları yoktur. Nefes almak için yüzeye çıkıp başlarının üstündeki nefes deliğinden hava çekerler." },
  { id: "p05-004", k: "Doğa", s: "Çubuklu balinaların ağzındaki süzgeç gibi \"balina çubukları\" hangi maddeden yapılmıştır?", d: "Keratin", y: ["Kemik", "Kıkırdak"], a: "Balina çubukları, saç ve tırnaklarımızdaki proteinle aynı olan keratinden oluşur. Kemik değildir." },
  { id: "p05-005", k: "Doğa", s: "Yunuslar karanlık ya da bulanık suda avlarını çoğunlukla nasıl bulur?", d: "Ekolokasyonla", y: ["Elektrik alanı algılayarak", "Koku alarak"], a: "Yunuslar tıklama sesleri çıkarır ve geri dönen yankıları dinleyerek avlarının yerini, boyutunu ve hareketini anlar." },
  { id: "p05-006", k: "Doğa", s: "Yunuslar uyurken boğulmamak için ne yapar?", d: "Beyinlerinin bir yarısıyla uyur", y: ["Solungaçlarla nefes alır", "Uyurken hiç nefes almaz"], a: "Yunuslarda beynin bir yarısı dinlenirken diğer yarısı uyanık kalır. Böylece nefes almak için yüzeye çıkmayı sürdürebilirler." },
  { id: "p05-007", k: "Doğa", s: "Erkeklerinin uzun, karmaşık ve tekrarlanan \"şarkılar\" söylemesiyle ünlü balina hangisidir?", d: "Kambur balina", y: ["Narval", "Gri balina"], a: "Kambur balina erkekleri saatlerce sürebilen, düzenli kalıplardan oluşan şarkılar söyler. Bu şarkılar zamanla değişir." },
  { id: "p05-008", k: "Doğa", s: "Dişli balinaların en büyüğü hangisidir?", d: "Kaşalot", y: ["Orka", "Beyaz balina"], a: "Kaşalot (ispermeçet balinası) dişli balinaların en büyüğüdür. Erkekleri 15 metreyi aşabilir." },
  { id: "p05-009", k: "Doğa", s: "Hayvanlar âleminde en büyük beyne sahip tür hangisidir?", d: "Kaşalot", y: ["Afrika fili", "İnsan"], a: "Kaşalotun beyni yaklaşık 8 kilogramla bilinen en büyük beyindir. Bir insan beyni ise yaklaşık 1,3-1,4 kilogramdır." },
  { id: "p05-010", k: "Doğa", s: "Kaşalotun ana besini nedir?", d: "Kalamar", y: ["Kril", "Deniz çayırı"], a: "Kaşalotlar derinlere dalarak çoğunlukla kalamar avlar. Midelerinde dev kalamar kalıntıları da bulunmuştur." },
  { id: "p05-011", k: "Doğa", s: "Narvalın başından uzanan uzun \"boynuz\" aslında nedir?", d: "Uzamış bir diş", y: ["Kemik bir boynuz", "Sertleşmiş kıllar"], a: "Narvalın sarmal \"boynuzu\", çoğunlukla erkeklerde görülen ve dudağı delip dışarı çıkan uzamış bir köpek dişidir." },
  { id: "p05-012", k: "Doğa", s: "\"Katil balina\" olarak da bilinen orka aslında hangi grubun en büyük üyesidir?", d: "Yunuslar", y: ["Köpekbalıkları", "Çubuklu balinalar"], a: "Orka, okyanus yunusları ailesinin en büyük türüdür. Erkekleri 8-9 metreye kadar ulaşabilir." },
  { id: "p05-013", k: "Doğa", s: "Deniz aslanlarını gerçek foklardan ayıran görünür özellik hangisidir?", d: "Dış kulak kepçesi", y: ["Bıyıklar", "Kürk"], a: "Deniz aslanlarının küçük dış kulak kepçeleri vardır. Gerçek fokların ise yalnızca kulak delikleri bulunur." },
  { id: "p05-014", k: "Doğa", s: "Morsların uzun dişleri hangi dişlerin uzamış hâlidir?", d: "Üst köpek dişleri", y: ["Alt kesici dişler", "Azı dişleri"], a: "Mors dişleri üst köpek dişlerinin uzamasıyla oluşur. Morslar bunları buzdan çıkarken tutunmak ve kavga etmek için kullanır." },
  { id: "p05-015", k: "Doğa", s: "Manatiler (deniz inekleri) ne ile beslenir?", d: "Su bitkileri", y: ["Balıklar", "Kabuklular"], a: "Manatiler otçuldur. Günlerinin büyük bölümünü deniz çayırı ve diğer su bitkilerini otlayarak geçirirler." },
  { id: "p05-016", k: "Doğa", s: "Deniz samurları kabuklu deniz canlılarını açmak için ne kullanır?", d: "Taş", y: ["Kuyruk", "Ön dişler"], a: "Deniz samurları sırtüstü yüzerken göğüslerine koydukları taşa kabukluları vurarak kırar. Bu, alet kullanımının bilinen bir örneğidir." },
  { id: "p05-017", k: "Doğa", s: "Kalın yağ tabakası olmayan deniz samuru soğuk sudan nasıl korunur?", d: "Çok yoğun kürküyle", y: ["Tüyleriyle", "Kalın pullarıyla"], a: "Deniz samurunun kürkü hayvanlar âleminin en yoğun kürkleri arasındadır. Kıllar arasında tutulan hava vücudu ısı kaybına karşı yalıtır." },
  { id: "p05-018", k: "Doğa", s: "Balinalar yavrularını nasıl besler?", d: "Sütle", y: ["Kusarak yarı sindirilmiş besinle", "Yavrular doğar doğmaz avlanır"], a: "Balinalar memelidir. Anneler yavrularını yağ oranı çok yüksek sütle emzirir; bu sayede yavrular hızla büyür." },
  { id: "p05-019", k: "Doğa", s: "Yunuslar hangi hayvan sınıfındadır?", d: "Memeliler", y: ["Balıklar", "Sürüngenler"], a: "Yunuslar akciğerle nefes alır, sıcakkanlıdır ve yavrularını sütle besler. Bu yüzden balık değil, memelidir." },
  { id: "p05-020", k: "Doğa", s: "Yumurtlayan memeliye örnek hangisidir?", d: "Ornitorenk", y: ["Kanguru", "Koala"], a: "Ornitorenk yumurtlar ama yavrusunu sütle besler. Yumurtlayan memelilere monotrem denir." },
  { id: "p05-021", k: "Doğa", s: "Ornitorenk dışında yumurtlayan diğer memeli grubu hangisidir?", d: "Ekidnalar", y: ["Armadillolar", "Kirpiler"], a: "Dikenli karıncayiyen olarak da bilinen ekidnalar, ornitorenkle birlikte yaşayan monotremleri oluşturur." },
  { id: "p05-022", k: "Doğa", s: "Erkek ornitorengin arka ayaklarında ne bulunur?", d: "Zehirli mahmuz", y: ["Perde olmayan pençe", "Koku bezi kesesi"], a: "Erkek ornitorenklerin arka bileklerinde zehir salgılayan mahmuzlar vardır. Zehir insanda şiddetli ağrıya yol açabilir." },
  { id: "p05-023", k: "Doğa", s: "Ornitoreng su altında gözleri kapalıyken avını nasıl bulur?", d: "Gagasındaki elektrik algılayıcılarla", y: ["Ekolokasyonla", "Isı algılayan çukurlarla"], a: "Ornitorengin gagası, avların kas hareketlerinin oluşturduğu zayıf elektrik alanlarını algılayan reseptörlerle doludur." },
  { id: "p05-024", k: "Doğa", s: "Kanguru yavrusu doğduğunda nasıldır?", d: "Çok küçük ve gelişmemiş", y: ["Annesinin yarısı boyunda", "Hemen zıplayabilecek kadar güçlü"], a: "Kanguru yavrusu fasulye tanesi büyüklüğünde doğar. Annesinin kesesine tırmanır ve aylarca orada emerek gelişir." },
  { id: "p05-025", k: "Doğa", s: "Koalaların neredeyse tek besini nedir?", d: "Okaliptüs yaprakları", y: ["Bambu", "Meyve"], a: "Koalalar neredeyse yalnızca okaliptüs yaprağı yer. Bu yapraklar besin değeri düşük ve sindirimi zor olduğundan koalalar çok uyur." },
  { id: "p05-026", k: "Doğa", s: "Koalalar doğal olarak hangi kıtada yaşar?", d: "Avustralya", y: ["Afrika", "Güney Amerika"], a: "Koalalar yalnızca Avustralya'nın doğusundaki okaliptüs ormanlarında doğal olarak bulunur." },
  { id: "p05-027", k: "Doğa", s: "Gerçek anlamda kanat çırparak uçabilen tek memeli grubu hangisidir?", d: "Yarasalar", y: ["Uçan sincaplar", "Kolugolar"], a: "Yarasalar kanat çırparak aktif uçuş yapabilen tek memelilerdir. Uçan sincaplar ve kolugolar yalnızca süzülür." },
  { id: "p05-028", k: "Doğa", s: "Yarasaların görme yeteneği hakkında hangisi doğrudur?", d: "Görebilirler", y: ["Tamamen kördürler", "Yalnızca kızılötesi görürler"], a: "\"Yarasa kadar kör\" deyimi yanlıştır. Bütün yarasalar görebilir; birçoğu ayrıca karanlıkta ekolokasyon kullanır." },
  { id: "p05-029", k: "Doğa", s: "Kanla beslenen vampir yarasalar doğal olarak nerede yaşar?", d: "Orta ve Güney Amerika", y: ["Doğu Avrupa", "Avustralya"], a: "Üç vampir yarasa türü de Amerika kıtasının sıcak bölgelerinde, Meksika'dan Güney Amerika'ya kadar yaşar." },
  { id: "p05-030", k: "Doğa", s: "En hızlı koşan kara hayvanı hangisidir?", d: "Çita", y: ["Aslan", "Antilop"], a: "Çita kısa mesafede saatte 100 kilometreyi aşan hızlara ulaşabilir. Ancak bu hızı yalnızca birkaç yüz metre sürdürebilir." },
  { id: "p05-031", k: "Doğa", s: "Çitayı diğer büyük kedilerden ayıran pençe özelliği nedir?", d: "Pençelerini tam geri çekemez", y: ["Pençesi yoktur", "Pençeleri zehirlidir"], a: "Çitanın pençeleri tam olarak içeri çekilmez. Koşu sırasında krampon gibi zemine tutunmasına yardım eder." },
  { id: "p05-032", k: "Doğa", s: "Büyük kediler arasında sürü hâlinde yaşamasıyla bilinen tür hangisidir?", d: "Aslan", y: ["Kaplan", "Leopar"], a: "Aslanlar, birbiriyle akraba dişiler ve birkaç erkekten oluşan sürüler hâlinde yaşar. Diğer büyük kediler çoğunlukla yalnızdır." },
  { id: "p05-033", k: "Doğa", s: "Aslan sürüsünde avlanmanın çoğunu kim yapar?", d: "Dişiler", y: ["Erkekler", "Genç erkekler"], a: "Aslan sürülerinde avların çoğunu dişiler birlikte yapar. Erkekler daha çok bölgeyi ve sürüyü korur." },
  { id: "p05-034", k: "Doğa", s: "Yaşayan en büyük kedi türü hangisidir?", d: "Kaplan", y: ["Aslan", "Jaguar"], a: "Kaplan, özellikle Sibirya (Amur) kaplanı, yaşayan en büyük kedi türüdür. Bazı erkekler 300 kilograma yaklaşabilir." },
  { id: "p05-035", k: "Doğa", s: "Bir kaplanı tıraş etseydiniz derisinde ne görürdünüz?", d: "Çizgiler", y: ["Benekler", "Düz turuncu renk"], a: "Kaplanların çizgileri yalnızca kürklerinde değil, derilerinde de koyu renkli izler olarak bulunur." },
  { id: "p05-036", k: "Doğa", s: "Zürafanın boynunda kaç omur vardır?", d: "7", y: ["14", "25"], a: "Zürafanın boynunda da insanlar gibi 7 omur bulunur. Fark, her bir omurun çok uzun olmasıdır." },
  { id: "p05-037", k: "Doğa", s: "Yaşayan en uzun boylu kara hayvanı hangisidir?", d: "Zürafa", y: ["Afrika fili", "Deve"], a: "Erkek zürafalar 5 metreyi aşabilen boylarıyla en uzun kara hayvanıdır. Bu sayede yüksek ağaç dallarına uzanırlar." },
  { id: "p05-038", k: "Doğa", s: "Yaşayan en büyük kara hayvanı hangisidir?", d: "Afrika savan fili", y: ["Asya fili", "Ak gergedan"], a: "Afrika savan fili yaşayan en büyük kara hayvanıdır. Erkekleri 6 tonu geçebilir." },
  { id: "p05-039", k: "Doğa", s: "Filin hortumu hangi organların birleşmesiyle oluşmuştur?", d: "Burun ve üst dudak", y: ["Dil ve alt çene", "Boyun ve gırtlak"], a: "Fil hortumu burun ile üst dudağın birleşip uzamasıyla oluşur. Binlerce kastan oluşan, kemiksiz ve çok hassas bir organdır." },
  { id: "p05-040", k: "Doğa", s: "Fillerin fildişinden uzun dişleri aslında hangi dişlerdir?", d: "Kesici dişler", y: ["Köpek dişleri", "Azı dişleri"], a: "Fillerin uzun dişleri, ömür boyu uzamaya devam eden üst kesici dişlerdir." },
  { id: "p05-041", k: "Doğa", s: "Kara memelileri arasında en uzun gebelik süresi hangi hayvana aittir?", d: "Fil", y: ["Zürafa", "Gergedan"], a: "Fillerin gebeliği yaklaşık 22 ay sürer. Bu, kara memelileri arasındaki en uzun gebelik süresidir." },
  { id: "p05-042", k: "Doğa", s: "Afrika fillerinin kocaman kulakları en çok hangi işe yarar?", d: "Vücut ısısını düşürmek", y: ["Yiyecek toplamak", "Yüzerken denge sağlamak"], a: "Fil kulakları ince ve damar doludur. Fil kulaklarını salladıkça kan serinler ve vücut ısısı düşer." },
  { id: "p05-043", k: "Doğa", s: "Filler kilometrelerce uzaktaki fillerle hangi tür seslerle iletişim kurabilir?", d: "Çok düşük frekanslı sesler", y: ["Ultrasonik çığlıklar", "Yalnızca hortum vuruşları"], a: "Filler insan kulağının duyamayacağı kadar düşük frekanslı gürlemeler çıkarır. Bu sesler havada ve yerde uzaklara yayılır." },
  { id: "p05-044", k: "Doğa", s: "Asya filini Afrika filinden ayırmanın en kolay yolu nedir?", d: "Daha küçük kulakları", y: ["Hortumunun olmaması", "Daha uzun kuyruğu"], a: "Asya fillerinin kulakları Afrika fillerininkinden belirgin biçimde küçüktür. Ayrıca genellikle daha küçük yapılıdırlar." },
  { id: "p05-045", k: "Doğa", s: "Devenin hörgücünde esas olarak ne depolanır?", d: "Yağ", y: ["Su", "Kan"], a: "Hörgüç su deposu değil, yağ deposudur. Deve besin bulamadığında bu yağı enerji için kullanır." },
  { id: "p05-046", k: "Doğa", s: "İki hörgüçlü deve türünün adı nedir?", d: "Baktriya devesi", y: ["Tek hörgüçlü deve", "Lama"], a: "Baktriya devesinin iki hörgücü vardır ve Orta Asya'nın soğuk çöllerine uyum sağlamıştır. Arap devesi ise tek hörgüçlüdür." },
  { id: "p05-047", k: "Doğa", s: "Lama ve alpakanın anavatanı hangi kıtadır?", d: "Güney Amerika", y: ["Asya", "Afrika"], a: "Lama ve alpaka, And Dağları'nda binlerce yıl önce evcilleştirilmiştir. Develerle akrabadırlar." },
  { id: "p05-048", k: "Doğa", s: "Dev pandanın beslenmesinin büyük kısmını ne oluşturur?", d: "Bambu", y: ["Okaliptüs", "Balık"], a: "Dev pandalar etçiller takımındandır ama beslenmelerinin yüzde 99 kadarı bambudur. Günde saatlerce bambu yerler." },
  { id: "p05-049", k: "Doğa", s: "Dev pandaların bambuyu kavramasını kolaylaştıran \"altıncı parmak\" nedir?", d: "Uzamış bir bilek kemiği", y: ["Gerçek bir parmak", "Sertleşmiş bir tırnak"], a: "Pandanın \"başparmağı\", bilekteki susam kemiğinin uzamasıyla oluşmuş bir çıkıntıdır. Bambuyu tutmaya yarar." },
  { id: "p05-050", k: "Doğa", s: "Dev pandalar doğada hangi ülkede yaşar?", d: "Çin", y: ["Japonya", "Hindistan"], a: "Dev pandalar yalnızca Çin'in orta kesimlerindeki dağlık bambu ormanlarında doğal olarak bulunur." },
  { id: "p05-051", k: "Doğa", s: "Kutup ayısının derisi ne renktir?", d: "Siyah", y: ["Beyaz", "Pembe"], a: "Kutup ayısının derisi siyahtır. Kılları ise pigmentsizdir; ışığı yansıttıkları için beyaz görünürler." },
  { id: "p05-052", k: "Doğa", s: "Kutup ayılarının ana besini nedir?", d: "Foklar", y: ["Penguenler", "Ren geyikleri"], a: "Kutup ayıları özellikle halkalı fok gibi fokları buz üzerinde avlar. Penguenler ise Kuzey Kutbu'nda yaşamaz." },
  { id: "p05-053", k: "Doğa", s: "Kutup ayıları doğada nerede yaşar?", d: "Arktik bölgede", y: ["Antarktika'da", "Patagonya'da"], a: "Kutup ayıları Kuzey Kutbu çevresindeki deniz buzu ve kıyılarda yaşar. Antarktika'da hiç ayı yoktur." },
  { id: "p05-054", k: "Doğa", s: "Kış uykusuna yatmasıyla bilinen kemirgen hangisidir?", d: "Dağ sıçanı", y: ["Kunduz", "Ev faresi"], a: "Dağ sıçanları (marmotlar) kışı yuvalarında, vücut ısıları ve kalp atışları çok düşmüş hâlde aylarca uyuyarak geçirir." },
  { id: "p05-055", k: "Doğa", s: "Kirpinin dikenleri aslında nedir?", d: "Değişime uğramış kıllar", y: ["Kemik çıkıntıları", "Sertleşmiş deri pulları"], a: "Kirpi dikenleri keratinden yapılmış, içi boş ve sertleşmiş kıllardır." },
  { id: "p05-056", k: "Doğa", s: "Oklu kirpi dikenleriyle kendini nasıl savunur?", d: "Dikenler dokunana saplanıp kopar", y: ["Dikenleri uzağa fırlatır", "Dikenlerle zehir enjekte eder"], a: "Oklu kirpi dikenlerini fırlatamaz. Uçları kancalı dikenler, dokunan hayvanın derisine saplanıp kolayca kopar." },
  { id: "p05-057", k: "Doğa", s: "Kunduzların ön dişleri neden turuncu renktedir?", d: "Minelerinde demir bulunur", y: ["Ağaç özsuyu boyar", "Çürük oldukları için"], a: "Kunduz dişlerinin minesinde demir içeren bir madde bulunur. Bu dişleri hem turuncu yapar hem de sertleştirir." },
  { id: "p05-058", k: "Doğa", s: "Kemirgenlerin kesici dişleri hakkında hangisi doğrudur?", d: "Ömür boyu uzamaya devam eder", y: ["Hiç değişmez", "Her yıl düşüp yenilenir"], a: "Kemirgenlerin kesici dişleri sürekli uzar. Bu yüzden sert şeyler kemirerek dişlerini aşındırmaları gerekir." },
  { id: "p05-059", k: "Doğa", s: "Tavşanlar hangi memeli takımında yer alır?", d: "Tavşanımsılar", y: ["Kemirgenler", "Böcekçiller"], a: "Tavşanlar kemirgen sanılsa da ayrı bir takım olan tavşanımsılardandır. Üst çenelerinde iki çift kesici diş bulunur." },
  { id: "p05-060", k: "Doğa", s: "Tavşanlar besinden daha fazla yararlanmak için ne yapar?", d: "Özel yumuşak dışkılarını yeniden yer", y: ["Besini kursakta saklar", "Geviş getirir"], a: "Tavşanlar kör bağırsakta oluşan besin değeri yüksek yumuşak dışkıyı doğrudan yiyerek bitkileri ikinci kez sindirir." },
  { id: "p05-061", k: "Doğa", s: "Dünyanın en büyük kemirgeni hangisidir?", d: "Kapibara", y: ["Kunduz", "Oklu kirpi"], a: "Güney Amerika'da yaşayan kapibara 60 kilogramı aşabilir. Suya çok yakın yaşar ve iyi yüzer." },
  { id: "p05-062", k: "Doğa", s: "Tembel hayvanların kürkü neden bazen yeşilimsi görünür?", d: "Kürklerinde alg yaşar", y: ["Yaprak yiyerek boyanırlar", "Kürkleri klorofil üretir"], a: "Tembel hayvanların kürkündeki oluklarda algler yaşar. Bu yeşilimsi renk onları ağaçlarda kamufle etmeye yardım eder." },
  { id: "p05-063", k: "Doğa", s: "Tembel hayvanlar genellikle ne zaman ağaçtan yere iner?", d: "Dışkılamak için", y: ["Her gece uyumak için", "Su içmek için her saat"], a: "Tembel hayvanlar zamanlarının neredeyse tamamını ağaçta geçirir. Genellikle haftada bir kadar dışkılamak için yere inerler." },
  { id: "p05-064", k: "Doğa", s: "Dev karıncayiyen karıncaları nasıl yer?", d: "Uzun yapışkan diliyle", y: ["Keskin dişleriyle çiğneyerek", "Ön ayaklarıyla ağzına atarak"], a: "Dev karıncayiyenin dişi yoktur. Uzun ve yapışkan dilini dakikada çok kez yuvaya sokup çıkararak karıncaları toplar." },
  { id: "p05-065", k: "Doğa", s: "Dokuz kuşaklı armadillo genellikle kaç yavru doğurur?", d: "Dört eş yavru", y: ["Tek yavru", "On iki yavru"], a: "Dokuz kuşaklı armadillo genellikle tek bir döllenmiş yumurtadan gelişen, genetik olarak aynı dört yavru doğurur." },
  { id: "p05-066", k: "Doğa", s: "Vücudu keratin pullarla kaplı memeli hangisidir?", d: "Pangolin", y: ["Armadillo", "Kirpi"], a: "Pangolinin vücudu üst üste binen keratin pullarla kaplıdır. Tehlikede top gibi kıvrılır. Armadillonun zırhı ise kemiklidir." },
  { id: "p05-067", k: "Doğa", s: "Gergedan boynuzu hangi maddeden oluşur?", d: "Keratin", y: ["Kemik", "Fildişi"], a: "Gergedan boynuzu, saçımız ve tırnağımızdaki proteinle aynı madde olan keratinden yapılmıştır; içinde kemik yoktur." },
  { id: "p05-068", k: "Doğa", s: "Hipopotamın derisinden salgılanan kırmızımsı sıvının görevi nedir?", d: "Güneşe ve mikroplara karşı korumak", y: ["Avını zehirlemek", "Yüzerken hızlanmak"], a: "Bu salgı ne kan ne de terdir. Güneş ışığını süzer ve mikropların çoğalmasını engellediği düşünülür." },
  { id: "p05-069", k: "Doğa", s: "Genetik çalışmalara göre hipopotamın yaşayan en yakın akrabaları hangileridir?", d: "Balinalar ve yunuslar", y: ["Atlar", "Filler"], a: "Hipopotamlar ile balinalar ortak bir atadan gelir. İki grup yaklaşık 50 milyon yıldan uzun süre önce ayrılmıştır." },
  { id: "p05-070", k: "Doğa", s: "Zebraların çizgileri hakkında hangisi doğrudur?", d: "Her bireyde farklıdır", y: ["Bütün zebralarda aynıdır", "Yaşlandıkça kaybolur"], a: "Zebraların çizgi deseni parmak izi gibi bireye özgüdür. Araştırmacılar bireyleri bu desenlerden tanıyabilir." },
  { id: "p05-071", k: "Doğa", s: "Atlar her ayaklarında kaç parmak üzerinde yürür?", d: "Bir", y: ["İki", "Üç"], a: "Atlar tek toynaklıdır. Her bacak tek bir parmağın ucundaki toynağa dayanır." },
  { id: "p05-072", k: "Doğa", s: "Atlar ayakta kısa süre uyuyabilir. Bunu ne sağlar?", d: "Bacaklarını kilitleyen bir yapı", y: ["Ağaçlara yaslanmaları", "Kuyruklarıyla dengede durmaları"], a: "Atların bacaklarındaki özel bağ ve kas düzeni eklemleri kilitler. Ancak derin uyku için yere uzanmaları gerekir." },
  { id: "p05-073", k: "Doğa", s: "İneklerin midesi kaç bölmeden oluşur?", d: "Dört", y: ["Bir", "İki"], a: "İnekler geviş getiren hayvanlardır. Mideleri işkembe, börkenek, kırkbayır ve şirden olmak üzere dört bölmelidir." },
  { id: "p05-074", k: "Doğa", s: "Geviş getirme ne demektir?", d: "Yutulan besini ağza geri getirip çiğnemek", y: ["Besini yanakta saklamak", "Yemeği iki kez avlamak"], a: "Geviş getirenler yuttukları otu ağızlarına geri getirip tekrar çiğner. Bu, sert bitki liflerinin sindirimini kolaylaştırır." },
  { id: "p05-075", k: "Doğa", s: "Kediler hangi tadı algılayamaz?", d: "Tatlı", y: ["Acı", "Ekşi"], a: "Kedilerde tatlı tadı algılayan reseptör geni çalışmaz. Et yiyen bir hayvan olarak şekere ihtiyaçları yoktur." },
  { id: "p05-076", k: "Doğa", s: "Evcil köpeğin atası hangi hayvandır?", d: "Kurt", y: ["Çakal", "Tilki"], a: "Genetik çalışmalar köpeklerin, bugün soyu tükenmiş eski bir kurt popülasyonundan evcilleştirildiğini gösterir." },
  { id: "p05-077", k: "Doğa", s: "Kedilerin bıyıkları en çok ne işe yarar?", d: "Dokunarak çevreyi algılamak", y: ["Koku almak", "Ses duymak"], a: "Kedi bıyıkları sinirlerle dolu dokunma kıllarıdır. Hava akımını ve dar aralıkları algılamalarına yardım eder." },
  { id: "p05-078", k: "Doğa", s: "Köpekler sıcakta esas olarak nasıl serinler?", d: "Dili dışarıda hızlı solunumla", y: ["Tüm vücuttan terleyerek", "Kulaklarını sallayarak"], a: "Köpeklerin ter bezleri azdır ve çoğu pati yastıklarındadır. Asıl serinleme yolu hızlı ve sık solumaktır." },
  { id: "p05-079", k: "Doğa", s: "Kedi gözlerinin karanlıkta parlamasının sebebi nedir?", d: "Gözün arkasındaki yansıtıcı tabaka", y: ["Gözlerin ışık üretmesi", "Gözyaşındaki fosfor"], a: "Kedilerin retinasının arkasında ışığı geri yansıtan bir tabaka vardır. Bu, loş ışıkta daha iyi görmelerini sağlar." },
  { id: "p05-080", k: "Doğa", s: "Köpeklerin renk görüşü hakkında hangisi doğrudur?", d: "Bazı renkleri ayırt edebilirler", y: ["Yalnızca siyah-beyaz görürler", "İnsandan çok daha fazla renk görürler"], a: "Köpekler iki tür renk hücresine sahiptir. Mavi ve sarı tonlarını ayırt eder, kırmızı ile yeşili karıştırırlar." },
  { id: "p05-081", k: "Doğa", s: "Domuzlar sıcak havada neden çamurda yuvarlanır?", d: "Serinlemek için", y: ["Yiyecek aramak için", "Kokularını gizlemek için"], a: "Domuzların işlevsel ter bezi çok azdır. Çamur buharlaşırken vücudu serinletir ve deriyi güneşten korur." },
  { id: "p05-082", k: "Doğa", s: "Fennek tilkisinin çok büyük kulakları hangi işe yarar?", d: "Isı atmaya ve avı duymaya", y: ["Kumda yüzmeye", "Su depolamaya"], a: "Sahra'da yaşayan fennek tilkisinin büyük kulakları fazla ısıyı dışarı verir ve kum altındaki böcekleri duymasına yardım eder." },
  { id: "p05-083", k: "Doğa", s: "Köpekgiller ailesinin en küçük türü hangisidir?", d: "Fennek tilkisi", y: ["Kızıl tilki", "Çakal"], a: "Kuzey Afrika çöllerinde yaşayan fennek tilkisi yaklaşık 1-1,5 kilogram ağırlığıyla en küçük köpekgildir." },
  { id: "p05-084", k: "Doğa", s: "Kutup tilkisinin kürkü kışın genellikle ne renk olur?", d: "Beyaz", y: ["Kızıl", "Siyah"], a: "Kutup tilkisi mevsime göre tüy değiştirir. Kışın karla uyumlu beyaz, yazın ise kahverengi-gri bir kürkü olur." },
  { id: "p05-085", k: "Doğa", s: "Kokarca kendini nasıl savunur?", d: "Kötü kokulu sıvı püskürterek", y: ["Zehirli ısırıkla", "Dikenlerini kabartarak"], a: "Kokarca, kuyruğunun altındaki bezlerden birkaç metre uzağa çok keskin kokulu bir sıvı püskürtebilir." },
  { id: "p05-086", k: "Doğa", s: "Virginia opossumu tehlikede hangi davranışıyla ünlüdür?", d: "Ölü taklidi yapar", y: ["Ağaca tırmanıp şarkı söyler", "Rengini değiştirir"], a: "Opossum tehlike anında hareketsiz yatar, ağzını açar ve kötü koku salgılar. İngilizcede bu davranışa \"playing possum\" denir." },
  { id: "p05-087", k: "Doğa", s: "Bütün memelileri tanımlayan özellik hangisidir?", d: "Yavrularını sütle beslemeleri", y: ["Hepsinin karada yaşaması", "Hepsinin canlı doğurması"], a: "Memelilerin ortak özelliği süt bezleridir. Ornitorenk gibi yumurtlayanlar ve balina gibi suda yaşayanlar da memelidir." },
  { id: "p05-088", k: "Doğa", s: "Memelilerin kalbi kaç odacıklıdır?", d: "Dört", y: ["İki", "Üç"], a: "Memelilerin ve kuşların kalbi dört odacıklıdır. Bu yapı temiz ve kirli kanın karışmasını önler." },
  { id: "p05-089", k: "Doğa", s: "Memelilerin orta kulağında kaç küçük kemik bulunur?", d: "Üç", y: ["Bir", "Beş"], a: "Memelilerde çekiç, örs ve üzengi kemikleri bulunur. Kuşlar ve sürüngenlerde ise orta kulakta tek kemik vardır." },
  { id: "p05-090", k: "Doğa", s: "Şempanzelerin termit avlamak için yaptığı şey nedir?", d: "Dal parçasını yuvaya sokmak", y: ["Taşla yuvayı ezmek", "Yuvayı suyla doldurmak"], a: "Şempanzeler ince bir dalı yapraklarından arındırıp termit yuvasına sokar, üzerine tutunan termitleri yer. Bunu ilk Jane Goodall gözlemledi." },
  { id: "p05-091", k: "Doğa", s: "Yaşayan en büyük primat hangisidir?", d: "Goril", y: ["Orangutan", "Şempanze"], a: "Goriller yaşayan en büyük primatlardır. Erkek goriller 150-200 kilogram ağırlığa ulaşabilir." },
  { id: "p05-092", k: "Doğa", s: "Gorillerin beslenmesi esas olarak neye dayanır?", d: "Bitkilere", y: ["Ete", "Balığa"], a: "Goriller çoğunlukla yaprak, gövde, filiz ve meyve yer. Bazen karınca ve termit gibi böcekler de tüketirler." },
  { id: "p05-093", k: "Doğa", s: "Orangutanlar doğal olarak hangi adalarda yaşar?", d: "Borneo ve Sumatra", y: ["Madagaskar ve Mauritius", "Java ve Bali"], a: "Orangutanlar yalnızca Endonezya ve Malezya'ya ait Borneo ve Sumatra adalarının yağmur ormanlarında yaşar." },
  { id: "p05-094", k: "Doğa", s: "\"Orangutan\" adı Malay dilinde ne anlama gelir?", d: "Orman insanı", y: ["Kırmızı maymun", "Ağaç kralı"], a: "\"Orang\" insan, \"hutan\" orman demektir. Ad, bu büyük kızıl kürklü maymunun ağaçlardaki yaşamına göndermedir." },
  { id: "p05-095", k: "Doğa", s: "İnsanın yaşayan en yakın akrabaları hangileridir?", d: "Şempanze ve bonobo", y: ["Goril ve orangutan", "Babun ve makak"], a: "DNA karşılaştırmaları, şempanze ve bonobonun insanla en yakın akraba olduğunu gösterir. Ortak atamız milyonlarca yıl önce yaşadı." },
  { id: "p05-096", k: "Doğa", s: "Lemurlar doğal olarak yalnızca nerede yaşar?", d: "Madagaskar", y: ["Borneo", "Yeni Zelanda"], a: "Lemurlar yalnızca Afrika'nın doğusundaki Madagaskar adasında doğal olarak bulunur." },
  { id: "p05-097", k: "Doğa", s: "Gibbonlar ağaçlarda esas olarak nasıl ilerler?", d: "Kollarıyla dallarda salınarak", y: ["Dört ayak üzerinde koşarak", "Dal dal süzülerek"], a: "Gibbonlar uzun kollarıyla daldan dala salınarak çok hızlı ilerler. Bu harekete brakiyasyon denir." },
  { id: "p05-098", k: "Doğa", s: "Japonya'da kışın sıcak su kaynaklarında yıkanmasıyla ünlü primat hangisidir?", d: "Japon makağı", y: ["Mandril", "Kapuçin"], a: "\"Kar maymunu\" da denen Japon makakları, soğuk kış günlerinde ısınmak için kaplıcalara girer." },
  { id: "p05-099", k: "Doğa", s: "Yüzündeki parlak kırmızı ve mavi renklerle tanınan primat hangisidir?", d: "Mandril", y: ["Bonobo", "Gibbon"], a: "Orta Afrika'da yaşayan mandrillerin, özellikle baskın erkeklerin yüzünde parlak kırmızı ve mavi renkler bulunur." },
  { id: "p05-100", k: "Doğa", s: "Geyiklerin boynuzları hakkında hangisi doğrudur?", d: "Her yıl düşüp yeniden çıkar", y: ["Ömür boyu hiç düşmez", "Yalnızca dişilerde bulunur"], a: "Geyik boynuzları kemikten oluşur ve her yıl düşüp yeniden çıkar. Keçi ve sığırların boynuzu ise kalıcıdır." },
  { id: "p05-101", k: "Doğa", s: "Hem erkeğinde hem dişisinde genellikle boynuz bulunan geyik türü hangisidir?", d: "Ren geyiği", y: ["Kızıl geyik", "Karaca"], a: "Ren geyiği, dişilerinin de düzenli olarak boynuz taşıdığı tek geyik türüdür. Diğer geyiklerde boynuz yalnızca erkeklerde bulunur." },
  { id: "p05-102", k: "Doğa", s: "Serengeti ile Masai Mara arasındaki büyük yıllık göçün en kalabalık hayvanı hangisidir?", d: "Gnu", y: ["Zürafa", "Fil"], a: "Her yıl bir milyondan fazla gnu, zebra ve ceylanlarla birlikte yağmurları ve taze otu izleyerek Tanzanya ile Kenya arasında göç eder." },
  { id: "p05-103", k: "Doğa", s: "Kar leoparı hangi sesi çıkaramaz?", d: "Kükreme", y: ["Hırlama", "Tıslama"], a: "Kar leoparı Panthera cinsindendir ama gırtlak yapısı nedeniyle kükreyemez. Bunun yerine hırlar, tıslar ve miyavlamaya benzer sesler çıkarır." },
  { id: "p05-104", k: "Doğa", s: "Amerika kıtasında yaşayan en büyük kedi türü hangisidir?", d: "Jaguar", y: ["Puma", "Vaşak"], a: "Jaguar Amerika kıtasının en büyük kedisi, dünyada da kaplan ve aslandan sonra üçüncü büyük kedidir." },
  { id: "p05-105", k: "Doğa", s: "\"Kara panter\" olarak adlandırılan hayvanlar genellikle nedir?", d: "Siyah renkli leopar ya da jaguar", y: ["Ayrı bir kedi türü", "Aslan ile kaplan melezi"], a: "Kara panterler, fazla siyah pigment taşıyan leopar ya da jaguarlardır. Yakından bakınca benekleri hâlâ görülebilir." },
  { id: "p05-106", k: "Doğa", s: "Kulaklarının ucundaki siyah tüy püskülleriyle tanınan kedi hangisidir?", d: "Vaşak", y: ["Puma", "Çita"], a: "Vaşakların kulak uçlarında belirgin siyah tüy püskülleri, yüzlerinde de favori benzeri uzun tüyler bulunur." },
  { id: "p05-107", k: "Doğa", s: "Türkiye'de doğal olarak yaşayan ayı türü hangisidir?", d: "Boz ayı", y: ["Kara ayı", "Güneş ayısı"], a: "Türkiye'de yaşayan tek ayı türü boz ayıdır. Özellikle Karadeniz ve Doğu Anadolu'nun ormanlık dağlarında görülür." },
  { id: "p05-108", k: "Doğa", s: "Benekli sırtlan topluluklarında hangisi doğrudur?", d: "Dişiler erkeklerden baskındır", y: ["Topluluğu en yaşlı erkek yönetir", "Erkekler yavrulara bakar"], a: "Benekli sırtlanlarda dişiler genellikle erkeklerden iri ve baskındır. Topluluğun hiyerarşisinin en üstünde dişiler yer alır." },
  { id: "p05-109", k: "Doğa", s: "Benekli sırtlanlar besinlerini çoğunlukla nasıl elde eder?", d: "Kendileri avlayarak", y: ["Yalnızca leş yiyerek", "Aslanların avını çalarak"], a: "Benekli sırtlanlar yalnızca leşçi sanılır ama besinlerinin büyük kısmını grup hâlinde avlayarak kendileri elde eder." },
  { id: "p05-110", k: "Doğa", s: "Mirketler (surikatlar) grup içinde güvenliği nasıl sağlar?", d: "Nöbetçi bırakarak", y: ["Toprağa gömülerek", "Ağaçlarda saklanarak"], a: "Mirket grubu yiyecek ararken bir birey yüksek bir yerde dik durup nöbet tutar ve yırtıcı görünce uyarı sesi çıkarır." },
  { id: "p05-111", k: "Doğa", s: "Bazı firavun faresi türleri hangi hayvanlarla mücadele etmeleriyle ünlüdür?", d: "Zehirli yılanlar", y: ["Timsahlar", "Kartallar"], a: "Firavun fareleri çok hızlı refleksleri ve kobra zehrine karşı kısmi dirençleri sayesinde zehirli yılanları avlayabilir." },
  { id: "p05-112", k: "Doğa", s: "Çıplak köstebek fareleri koloni yapısıyla hangi böceklere benzer?", d: "Arılar ve karıncalar", y: ["Kelebekler", "Çekirgeler"], a: "Çıplak köstebek farelerinde yalnızca bir kraliçe ürer, diğerleri işçi olarak çalışır. Bu düzen memelilerde çok nadirdir." },
  { id: "p05-113", k: "Doğa", s: "Köstebeğin kürek gibi geniş ön ayakları ne işe yarar?", d: "Toprak kazmaya", y: ["Yüzmeye", "Ağaca tırmanmaya"], a: "Köstebekler hayatlarının çoğunu yer altında geçirir. Güçlü ve geniş ön ayaklarıyla tüneller kazarlar." },
  { id: "p05-114", k: "Doğa", s: "En çok türe sahip memeli takımı hangisidir?", d: "Kemirgenler", y: ["Primatlar", "Etçiller"], a: "Fareler, sincaplar, kunduzlar ve kapibaralar gibi kemirgenler, memeli türlerinin yaklaşık yüzde 40'ını oluşturur." },
  { id: "p05-115", k: "Doğa", s: "Sincapların toprağa gömüp unuttuğu tohumlar doğada ne işe yarar?", d: "Yeni ağaçların yetişmesine", y: ["Toprağı zehirlemeye", "Başka sincapları uzak tutmaya"], a: "Sincaplar kış için tohum ve fındık gömer. Bulamadıkları tohumlar filizlenir; böylece ormanların yayılmasına katkı sağlarlar." },
  { id: "p05-116", k: "Doğa", s: "Uçan sincaplar havada nasıl ilerler?", d: "Deri zarlarıyla süzülerek", y: ["Kanat çırparak", "Kuyruklarını pervane gibi döndürerek"], a: "Uçan sincapların ön ve arka bacakları arasında deri zar bulunur. Ağaçtan atlayıp bu zarı açarak süzülürler." },
  { id: "p05-117", k: "Doğa", s: "Hamsterlar yiyeceklerini yuvalarına taşımak için neyi kullanır?", d: "Yanak keselerini", y: ["Karınlarındaki keseyi", "Kuyruklarını"], a: "Hamsterların yanaklarında esneyebilen keseler vardır. Yiyeceği bu keselere doldurup yuvalarındaki depoya taşırlar." },
  { id: "p05-118", k: "Doğa", s: "Kobaylar (gine domuzları) insanlar gibi hangi vitamini kendileri üretemez?", d: "C vitamini", y: ["D vitamini", "K vitamini"], a: "Kobaylar, insanlar gibi C vitamini üretemez. Bu yüzden besinlerinde yeterli C vitamini bulunması gerekir." },
  { id: "p05-119", k: "Doğa", s: "Yaşayan en büyük keseli hayvan hangisidir?", d: "Kırmızı kanguru", y: ["Koala", "Vombat"], a: "Kırmızı kanguru yaşayan en büyük keselidir. Erkekleri dik durduğunda bir yetişkin insan boyuna ulaşabilir." },
  { id: "p05-120", k: "Doğa", s: "Tazmanya canavarı bugün doğal olarak nerede yaşar?", d: "Tazmanya adasında", y: ["Yeni Zelanda'da", "Madagaskar'da"], a: "Etçil bir keseli olan Tazmanya canavarı bugün yalnızca Avustralya'nın güneyindeki Tazmanya adasında doğal olarak bulunur." },
  { id: "p05-121", k: "Doğa", s: "Vombatların dışkısı hangi şekliyle ünlüdür?", d: "Küp", y: ["Spiral", "Halka"], a: "Vombatlar küp biçimli dışkı bırakır. Bu şekil bağırsak duvarının farklı esnekliğe sahip bölgelerinden kaynaklanır." },
  { id: "p05-122", k: "Doğa", s: "Toprak kazan vombatın kesesinin ağzı hangi yöne açılır?", d: "Arkaya", y: ["Öne", "Yana"], a: "Vombatın kesesi arkaya doğru açılır. Böylece anne tünel kazarken kesedeki yavruya toprak dolmaz." },
  { id: "p05-123", k: "Doğa", s: "ABD ve Kanada'da doğal olarak yaşayan tek keseli hayvan hangisidir?", d: "Virginia opossumu", y: ["Rakun", "Kokarca"], a: "Virginia opossumu Meksika'nın kuzeyinde yaşayan tek keselidir. Yavrularını kanguru gibi kesede taşır." },
  { id: "p05-124", k: "Doğa", s: "Afalina yunuslarının birbirini tanımak için kullandığı kişisel ses nedir?", d: "İmza ıslığı", y: ["Kuyruk vuruşu", "Diş gıcırtısı"], a: "Her afalina yunusunun kendine özgü bir ıslığı vardır. Diğerleri bu ıslığı taklit ederek ona bir ad gibi seslenebilir." },
  { id: "p05-125", k: "Doğa", s: "Çıkardığı çok çeşitli seslerden dolayı \"denizlerin kanaryası\" denen balina hangisidir?", d: "Beyaz balina (beluga)", y: ["Mavi balina", "Kaşalot"], a: "Beyaz balinalar ıslık, cıvıltı ve tıklamalardan oluşan çok çeşitli sesler çıkarır. Bu yüzden denizcilerin ilgisini çekmiştir." },
  { id: "p05-126", k: "Doğa", s: "Beyaz balinayı (beluga) birçok balinadan ayıran özellik hangisidir?", d: "Başını sağa sola çevirebilmesi", y: ["Solungaçlarının olması", "Yumurtlaması"], a: "Belugaların boyun omurları kaynaşmamıştır. Bu sayede çoğu balinanın aksine başlarını çevirebilir ve eğebilirler." },
  { id: "p05-127", k: "Doğa", s: "En uzun yaşadığı bilinen memeli hangisidir?", d: "Grönland balinası", y: ["Asya fili", "Mavi balina"], a: "Grönland balinalarının 200 yılı aşkın yaşayabildiği tahmin edilir. Bu, memeliler için bilinen en uzun ömürdür." },
  { id: "p05-128", k: "Doğa", s: "Kambur balinaların \"kabarcık ağı\" yöntemi nedir?", d: "Balıkları kabarcık perdesiyle toplamak", y: ["Kabarcıklarla dinlenmek", "Kabarcıklarla eş çağırmak"], a: "Kambur balinalar balık sürüsünün altında daire çizerek hava kabarcıkları bırakır. Toplanan balıkları ağızlarını açıp yukarı doğru yükselerek yutarlar." },
  { id: "p05-129", k: "Doğa", s: "Gri balinalar çoğunlukla nasıl beslenir?", d: "Deniz dibindeki çamuru süzerek", y: ["Fok avlayarak", "Yüzeydeki yosunları yiyerek"], a: "Gri balinalar yan yatıp deniz dibinden çamur alır ve balina çubuklarıyla süzerek içindeki küçük kabukluları yer." },
  { id: "p05-130", k: "Doğa", s: "Balinalar yüzerken kuyruklarını nasıl hareket ettirir?", d: "Yukarı ve aşağı", y: ["Sağa ve sola", "Kendi ekseninde döndürerek"], a: "Balinaların kuyruk yüzgeci yataydır ve yukarı-aşağı hareket eder. Balıkların dikey kuyruğu ise yana doğru hareket eder." },
  { id: "p05-131", k: "Doğa", s: "Deniz fillerine adını veren özellik nedir?", d: "Erkeklerin hortuma benzeyen burnu", y: ["Fildişi gibi dişleri", "Gri ve kırışık derileri"], a: "Erkek deniz fillerinin şişirebildikleri iri bir burunları vardır. Bu burnu yüksek sesli çağrılar için kullanırlar." },
  { id: "p05-132", k: "Doğa", s: "Manatilerin karada yaşayan en yakın akrabası hangisidir?", d: "Fil", y: ["Mors", "Hipopotam"], a: "Manati ve dugonglar, fillerle ortak bir atadan gelir. Hatta manatilerin tırnakları fil tırnaklarına benzer." },
  { id: "p05-133", k: "Doğa", s: "Dugong hangi hayvan grubunun üyesidir?", d: "Deniz inekleri", y: ["Foklar", "Yunuslar"], a: "Dugong, manatilerle birlikte deniz inekleri grubunu oluşturur. Sığ kıyı sularında deniz çayırı otlayarak yaşar." },
  { id: "p05-134", k: "Doğa", s: "Deniz samurları uyurken akıntıyla sürüklenmemek için ne yapar?", d: "Birbirlerine ya da yosunlara tutunur", y: ["Dibe dalıp uyur", "Kayalara tırmanır"], a: "Deniz samurları sırtüstü uyurken birbirlerinin patisini tutar ya da kendilerini dev yosunlara dolar." },
  { id: "p05-135", k: "Doğa", s: "Çubuklu balinaların kaç nefes deliği vardır?", d: "İki", y: ["Bir", "Dört"], a: "Çubuklu balinaların iki, yunuslar ve kaşalot gibi dişli balinaların ise tek nefes deliği vardır." },
  { id: "p05-136", k: "Doğa", s: "Orkalar genellikle nasıl yaşar?", d: "Aile grupları hâlinde", y: ["Tamamen yalnız", "Yalnızca erkeklerden oluşan gruplarda"], a: "Orkalar çoğunlukla yaşlı bir dişinin etrafında toplanan, anne soyuna dayalı aile grupları hâlinde yaşar ve birlikte avlanır." },
  { id: "p05-137", k: "Doğa", s: "Fosil kayıtlarına göre balinaların uzak ataları nerede yaşıyordu?", d: "Karada", y: ["Yalnızca derin denizde", "Göllerde balık olarak"], a: "Balinalar, yaklaşık 50 milyon yıl önce karada yaşayan dört bacaklı memelilerden evrimleşmiştir." },
  { id: "p05-138", k: "Doğa", s: "Foklar buz gibi sularda vücut ısılarını nasıl korur?", d: "Derinin altındaki kalın yağ tabakasıyla", y: ["Sürekli titreyerek", "Kanlarındaki antifrizle"], a: "Fokların derisi altındaki kalın yağ tabakası iyi bir yalıtım sağlar ve enerji deposu işlevi görür." },
  { id: "p05-139", k: "Doğa", s: "Grönland foku (arp foku) yavruları doğduklarında hangi renktedir?", d: "Beyaz", y: ["Siyah", "Kızıl"], a: "Arp foku yavruları yumuşak beyaz bir kürkle doğar. Birkaç hafta içinde bu kürk dökülür ve gri benekli bir kürk çıkar." },
  { id: "p05-140", k: "Doğa", s: "Morslar deniz dibindeki midyeleri bulmak için en çok neyi kullanır?", d: "Hassas bıyıklarını", y: ["Ekolokasyonu", "Uzun dişlerini"], a: "Morsların ağzının çevresinde yüzlerce hassas bıyık vardır. Bulanık dipte midyeleri dokunarak bulur, sonra emerek yerler." },
  { id: "p05-141", k: "Doğa", s: "Zürafanın yaşayan en yakın akrabası hangisidir?", d: "Okapi", y: ["Deve", "Zebra"], a: "Orta Afrika ormanlarında yaşayan okapinin bacakları zebra gibi çizgilidir ama zürafayla aynı ailededir." },
  { id: "p05-142", k: "Doğa", s: "Zürafanın uzun ve kavrayıcı dili en çok ne işe yarar?", d: "Dikenli dallardan yaprak koparmaya", y: ["Su içerken pompa görevi görmeye", "Yırtıcıları kovmaya"], a: "Zürafalar uzun dillerini dalın etrafına dolayıp akasyanın dikenleri arasından yaprak koparır." },
  { id: "p05-143", k: "Doğa", s: "Hipopotamlar suda genellikle nasıl hareket eder?", d: "Dipte yürüyerek ya da sekerek", y: ["Balık gibi yüzerek", "Sırtüstü kürek çekerek"], a: "Hipopotamlar iyi yüzücü değildir. Suyun dibinde yürür ya da ayaklarıyla dipten itilerek sekerler." },
  { id: "p05-144", k: "Doğa", s: "Hipopotamlar ne ile beslenir?", d: "Ot", y: ["Balık", "Timsah yumurtası"], a: "Hipopotamlar gündüzü suda geçirir, geceleri karaya çıkıp kilometrelerce yürüyerek ot yer." },
  { id: "p05-145", k: "Doğa", s: "Kuzey Amerika'nın en ağır kara hayvanı hangisidir?", d: "Amerika bizonu", y: ["Boz ayı", "Kanada geyiği"], a: "Amerika bizonunun erkekleri 900 kilogramı aşabilir. Bir zamanlar milyonlarcası Büyük Ovalar'da dolaşıyordu." },
  { id: "p05-146", k: "Doğa", s: "Uzun tüylü yak hangi bölgenin yüksek dağlarında yaşar?", d: "Tibet ve Himalayalar", y: ["And Dağları", "Alpler"], a: "Yaklar kalın kürkleri ve büyük akciğerleriyle Tibet Platosu'nun soğuk ve oksijeni az yüksekliklerine uyum sağlamıştır." },
  { id: "p05-147", k: "Doğa", s: "Misk öküzleri kurt saldırısına karşı nasıl savunma yapar?", d: "Yavruların çevresinde halka olur", y: ["Dağılıp kaçar", "Suya girer"], a: "Misk öküzleri tehlikede yavruları ortaya alıp boynuzları dışa dönük bir halka oluşturur." },
  { id: "p05-148", k: "Doğa", s: "Bir kurt sürüsü genellikle kimlerden oluşur?", d: "Anne, baba ve yavruları", y: ["Birbirine yabancı erkekler", "Yalnızca dişiler"], a: "Doğadaki kurt sürüleri çoğunlukla üreyen bir çift ve farklı yaşlardaki yavrularından oluşan bir ailedir." },
  { id: "p05-149", k: "Doğa", s: "Kurtlar uluyarak en çok ne yapar?", d: "Sürüyle haberleşir", y: ["Ayı korkutur", "Avını uyutur"], a: "Uluma, kurtların sürü üyelerini toplamak ve diğer sürülere bölgelerini bildirmek için kullandığı uzak mesafe sesidir." },
  { id: "p05-150", k: "Doğa", s: "Gözlerinin çevresindeki siyah \"maske\" ile tanınan hayvan hangisidir?", d: "Rakun", y: ["Kokarca", "Porsuk"], a: "Rakunlar Kuzey Amerika kökenlidir. Yüzlerindeki siyah maske ve halkalı kuyruklarıyla kolayca tanınırlar." },
  { id: "p05-151", k: "Doğa", s: "Kızıl panda hakkında hangisi doğrudur?", d: "Kendi ailesinin tek yaşayan türüdür", y: ["Dev pandanın yavrusudur", "Bir rakun türüdür"], a: "Kızıl panda, dev panda gibi bambu yese de ona yakın akraba değildir. Kendi ailesinin yaşayan tek üyesidir." },
  { id: "p05-152", k: "Doğa", s: "En küçük ayı türü hangisidir?", d: "Güneş ayısı", y: ["Kara ayı", "Gözlüklü ayı"], a: "Güneydoğu Asya ormanlarında yaşayan güneş ayısı en küçük ayıdır. Göğsündeki açık renkli lekeden dolayı bu adı alır." },
  { id: "p05-153", k: "Doğa", s: "Boz ayılar Alaska'da sonbahara hazırlanırken hangi balığı avlamasıyla ünlüdür?", d: "Somon", y: ["Ton balığı", "Sardalya"], a: "Boz ayılar akıntıya karşı yüzen somonları nehirlerde yakalar. Bu yağlı besin, kış öncesi kilo almalarını sağlar." },
  { id: "p05-154", k: "Doğa", s: "Kangurular kuyruklarını ne için kullanır?", d: "Denge ve destek için", y: ["Yüzmek için", "Ağaçlara asılmak için"], a: "Kanguru kuyruğu zıplarken dengeyi sağlar. Yavaş hareket ederken de beşinci bir bacak gibi vücudu taşır." },
  { id: "p05-155", k: "Doğa", s: "Yarasalar dinlenirken genellikle nasıl durur?", d: "Baş aşağı asılı", y: ["Sırtüstü yatarak", "Dik oturarak"], a: "Yarasalar ayaklarıyla tutunup baş aşağı asılır. Bu duruş, bıraktıkları anda havalanmalarını kolaylaştırır." },
  { id: "p05-156", k: "Doğa", s: "Yarasanın kanadı hangi yapıdan oluşur?", d: "Uzun parmaklar arasındaki deri zardan", y: ["Tüylerden", "Kitin plakalardan"], a: "Yarasa kanadı, insan eline benzeyen kemik yapısında, çok uzamış parmaklar arasında gerilmiş ince bir deri zardır." },
  { id: "p05-157", k: "Doğa", s: "Meyve ve nektarla beslenen yarasaların doğaya katkısı nedir?", d: "Tozlaşma ve tohum yayma", y: ["Toprağı havalandırma", "Suyu temizleme"], a: "Birçok tropik bitki tozlaşma ve tohum yayılımı için yarasalara bağımlıdır. Agav ve muz bunların örnekleridir." },
  { id: "p05-158", k: "Doğa", s: "Aslanlarda yele genellikle hangi bireylerde bulunur?", d: "Yetişkin erkeklerde", y: ["Yetişkin dişilerde", "Yalnızca yavrularda"], a: "Yele, yetişkin erkek aslanların belirgin bir özelliğidir. Koyu ve gür yele, sağlıklı bir erkeğin işareti olarak görülür." },
  { id: "p05-159", k: "Doğa", s: "Suyu ve yüzmeyi sevmesiyle bilinen büyük kedi hangisidir?", d: "Kaplan", y: ["Çita", "Kar leoparı"], a: "Kaplanlar çoğu kedinin aksine suya rahatça girer. İyi yüzücüdürler ve sıcak günlerde suda serinlerler." },
  { id: "p05-160", k: "Doğa", s: "Leoparlar avlarını sırtlan ve aslanlardan korumak için ne yapar?", d: "Ağaca taşır", y: ["Suya gömer", "Toprağa gömer"], a: "Leoparlar çok güçlüdür. Kendilerinden ağır avları bile ağaca çıkarıp dallar arasında güvenle yiyebilirler." },
  { id: "p05-161", k: "Doğa", s: "Jaguarlar diğer büyük kedilerden farklı olarak avlarını sıklıkla nasıl öldürür?", d: "Kafatasını ısırarak delerek", y: ["Zehirli ısırıkla", "Suda boğarak"], a: "Jaguarın ısırığı çok güçlüdür. Avının kafatasını ya da kaplumbağa kabuğunu ısırarak delebilir." },
  { id: "p05-162", k: "Doğa", s: "Fil sürüsüne genellikle kim önderlik eder?", d: "Yaşlı bir dişi", y: ["En iri erkek", "En genç birey"], a: "Fil sürülerini, deneyimiyle su ve yiyecek yerlerini bilen yaşlı bir dişi (matriark) yönetir. Yetişkin erkekler genellikle ayrı yaşar." },
  { id: "p05-163", k: "Doğa", s: "Fil yavrusu annesini nasıl emer?", d: "Ağzıyla", y: ["Hortumuyla", "Kulağıyla"], a: "Fil yavruları hortumlarını kenara kaldırıp ağızlarıyla emer. Hortumlarını kullanmayı öğrenmeleri aylar sürer." },
  { id: "p05-164", k: "Doğa", s: "Filler yaşamları boyunca azı dişlerini kaç kez yeniler?", d: "Altı kez", y: ["Bir kez", "Hiç yenilemez"], a: "Fillerin ömürleri boyunca altı takım azı dişi sırayla öne doğru ilerler. Son takım da aşınınca beslenmeleri zorlaşır." },
  { id: "p05-165", k: "Doğa", s: "Develerin kum fırtınasına karşı korunmasını sağlayan özellik hangisidir?", d: "Kapanabilen burun delikleri", y: ["Kalın boynuzları", "Kısa kulakları"], a: "Develer burun deliklerini kapatabilir. Çift sıra uzun kirpikleri de gözlerini kuma karşı korur." },
  { id: "p05-166", k: "Doğa", s: "Deve ve akrabalarının alyuvarlarının şekli diğer memelilerden nasıl farklıdır?", d: "Ovaldir", y: ["Kare biçimlidir", "Yıldız biçimlidir"], a: "Memelilerde alyuvarlar genellikle yuvarlaktır. Develer ve akrabalarında ise ovaldir. Bunun susuz kaldıklarında kanın akışını kolaylaştırdığı düşünülür." },
  { id: "p05-167", k: "Doğa", s: "Evcil domuzun atası hangi hayvandır?", d: "Yaban domuzu", y: ["Su aygırı", "Pekari"], a: "Evcil domuz, Avrasya'da yaşayan yaban domuzundan birbirinden bağımsız olarak birkaç kez evcilleştirilmiştir." },
  { id: "p05-168", k: "Doğa", s: "Evcil sığırın soyu tükenmiş atası hangisidir?", d: "Yaban sığırı (aurochs)", y: ["Bizon", "Yak"], a: "Evcil sığırlar yaban sığırından gelir. Bu iri hayvanın son bireyi 1627'de Polonya'da öldü." },
  { id: "p05-169", k: "Doğa", s: "Evcil keçinin atası olan yaban keçisi ilk nerede evcilleştirildi?", d: "Bereketli Hilal'de", y: ["Avustralya'da", "Güney Amerika'da"], a: "Keçiler yaklaşık 10 bin yıl önce Anadolu'nun güneydoğusu ve Zagros Dağları'nı da kapsayan bölgede evcilleştirildi." },
  { id: "p05-170", k: "Doğa", s: "Evcil koyunun yabani atası hangisidir?", d: "Muflon", y: ["Dağ keçisi", "Ceylan"], a: "Evcil koyunun atası Asya muflonudur. Koyun, ilk evcilleştirilen çiftlik hayvanları arasındadır." },
  { id: "p05-171", k: "Doğa", s: "Evcil eşeğin atası hangisidir?", d: "Afrika yaban eşeği", y: ["Zebra", "Asya yaban atı"], a: "Eşek, Kuzeydoğu Afrika'da yaşayan Afrika yaban eşeğinden evcilleştirilmiştir." },
  { id: "p05-172", k: "Doğa", s: "Evcil kedinin atası hangisidir?", d: "Yakın Doğu yaban kedisi", y: ["Vaşak", "Karakulak"], a: "Evcil kediler, Yakın Doğu'da tarımla birlikte insanların yakınında yaşamaya başlayan yaban kedilerinden gelir." },
  { id: "p05-173", k: "Doğa", s: "Katır hangi iki hayvanın çiftleşmesinden doğar?", d: "Erkek eşek ve dişi at", y: ["Zebra ve at", "Deve ve lama"], a: "Katırlar erkek eşek ile dişi atın yavrusudur. Güçlü ve dayanıklıdırlar ama genellikle kısırdırlar." },
  { id: "p05-174", k: "Doğa", s: "Bir atın yaşı yaklaşık olarak nereden tahmin edilir?", d: "Dişlerinden", y: ["Toynak renginden", "Yelesinin uzunluğundan"], a: "Atların dişleri yaşla birlikte belirli biçimde aşınır ve şekil değiştirir. Uzmanlar buna bakarak yaşı tahmin eder." },
  { id: "p05-175", k: "Doğa", s: "Keçilerin göz bebekleri hangi şekildedir?", d: "Yatay dikdörtgen", y: ["Dikey yarık", "Tam yuvarlak"], a: "Keçi ve koyunların yatay göz bebekleri geniş bir görüş açısı sağlar. Bu, otlarken yırtıcıları fark etmelerine yardım eder." },
  { id: "p05-176", k: "Doğa", s: "Boğa güreşinde boğanın pelerine saldırmasının asıl sebebi nedir?", d: "Pelerinin hareketi", y: ["Pelerinin kırmızı rengi", "Pelerinin kokusu"], a: "Sığırlar kırmızıyı yeşilden iyi ayırt edemez. Boğayı kızdıran rengi değil, pelerinin sallanmasıdır." },
  { id: "p05-177", k: "Doğa", s: "Afrika yaban köpeklerinin kürk desenleri hakkında hangisi doğrudur?", d: "Her bireyde farklıdır", y: ["Hepsi tek renk siyahtır", "Kışın beyaza döner"], a: "Afrika yaban köpeklerinin siyah, sarı ve beyaz lekelerden oluşan deseni her bireyde farklıdır." },
  { id: "p05-178", k: "Doğa", s: "Gergedanların görme ve koku duyuları için hangisi doğrudur?", d: "Görmeleri zayıf, kokuları güçlüdür", y: ["Gece görüşleri kusursuzdur", "Koku alamazlar"], a: "Gergedanların görmesi zayıftır. Çevrelerini daha çok güçlü koku alma ve işitme duyularıyla algılarlar." },
  { id: "p05-179", k: "Doğa", s: "Kuyruğunu bir dala sarıp asılabilen maymunlar hangi kıtada yaşar?", d: "Güney ve Orta Amerika", y: ["Afrika", "Asya"], a: "Örümcek maymunu ve uluyan maymun gibi bazı Yeni Dünya maymunlarının kavrayıcı kuyrukları vardır. Afrika ve Asya maymunlarında bu yetenek yoktur." },
  { id: "p05-180", k: "Doğa", s: "Uluyan maymunlar yüksek seslerini en çok ne için kullanır?", d: "Bölgelerini duyurmak", y: ["Avlarını korkutmak", "Ekolokasyon yapmak"], a: "Uluyan maymunların sesleri kilometrelerce duyulabilir. Gruplar bu seslerle birbirlerine yerlerini bildirerek karşılaşmaktan kaçınır." },
  { id: "p05-181", k: "Doğa", s: "Bonobolar doğada yalnızca hangi ülkede yaşar?", d: "Kongo Demokratik Cumhuriyeti", y: ["Endonezya", "Brezilya"], a: "Bonobolar yalnızca Kongo Demokratik Cumhuriyeti'nde, Kongo Nehri'nin güneyindeki ormanlarda yaşar." },
  { id: "p05-182", k: "Doğa", s: "Şempanzeler ne ile beslenir?", d: "Meyve ağırlıklı karışık besinle", y: ["Yalnızca yaprakla", "Yalnızca etle"], a: "Şempanzeler çoğunlukla meyve yer; yaprak, böcek ve bazen avladıkları küçük memelilerle beslenmelerini tamamlar." },
  { id: "p05-183", k: "Doğa", s: "Orangutanlar geceyi genellikle nerede geçirir?", d: "Ağaçta yaptıkları yuvada", y: ["Mağarada", "Toprak altında"], a: "Orangutanlar neredeyse her akşam ağaçta dal ve yapraklardan yeni bir yuva yapar ve geceyi orada geçirir." },
  { id: "p05-184", k: "Doğa", s: "Yetişkin erkek gorillere sırtlarındaki renkten dolayı ne ad verilir?", d: "Gümüş sırt", y: ["Kızıl sırt", "Altın sırt"], a: "Yetişkin erkek gorillerin sırtındaki tüyler gümüşi griye döner. Gümüş sırtlı erkek grubu korur ve yönlendirir." },
  { id: "p05-185", k: "Doğa", s: "Sivri fareler gibi çok küçük memeliler neden sık sık yemek zorundadır?", d: "Metabolizmaları çok hızlıdır", y: ["Mideleri yoktur", "Besin depolayamazlar çünkü dişsizdirler"], a: "Küçük vücutlar hızla ısı kaybeder. Bu yüzden sivri fareler çok hızlı bir metabolizmayla yaşar ve sürekli beslenmeleri gerekir." },
  { id: "p05-186", k: "Doğa", s: "Ekidnalar esas olarak ne ile beslenir?", d: "Karınca ve termit", y: ["Ot", "Balık"], a: "Ekidnalar uzun burunları ve yapışkan dilleriyle karınca ve termit yuvalarından böcek toplar." },
  { id: "p05-187", k: "Doğa", s: "Avustralya'nın yabani köpeği hangisidir?", d: "Dingo", y: ["Çakal", "Kayot"], a: "Dingolar binlerce yıl önce Avustralya'ya getirilmiş köpeklerin yabanileşmiş soyundandır ve kıtanın en büyük kara yırtıcısıdır." },
  { id: "p05-188", k: "Doğa", s: "Ornitorenk yavrularını nasıl besler?", d: "Derisinden sızan sütle", y: ["Memesinden emzirerek", "Kusarak"], a: "Ornitorenklerin meme ucu yoktur. Süt, karın derisindeki bezlerden sızar ve yavrular bunu yalar." },
  { id: "p05-189", k: "Doğa", s: "Kapibaraları doğada çoğunlukla nerede görürsünüz?", d: "Göl ve nehir kenarlarında", y: ["Çöllerde", "Karla kaplı dağlarda"], a: "Kapibaralar yarı suda yaşar. Gözleri, kulakları ve burun delikleri başlarının üstündedir; suda saklanırken bunları açıkta tutarlar." },
  { id: "p05-190", k: "Doğa", s: "Kunduzlar yaşadıkları dereleri neyle değiştirir?", d: "Dal ve çamurdan barajlarla", y: ["Taş duvarlarla", "Kum tepeleriyle"], a: "Kunduzlar dal, taş ve çamurdan barajlar kurarak göletler oluşturur. Bu göletler birçok canlıya yaşam alanı sağlar." },
  { id: "p05-191", k: "Doğa", s: "Kunduzların yassı ve pullu kuyruğu ne işe yarar?", d: "Yüzmeye ve tehlike uyarısına", y: ["Ağaç kesmeye", "Avlanmaya"], a: "Kunduzlar kuyruklarını suda dümen gibi kullanır. Tehlike anında suya şaşkın bir sesle vurarak diğerlerini uyarırlar." },
  { id: "p05-192", k: "Doğa", s: "Yaşayan en küçük memelilerden biri olarak bilinen hayvan hangisidir?", d: "Etrüsk sivri faresi", y: ["Hamster", "Gelincik"], a: "Etrüsk sivri faresi yalnızca 2 gram kadar ağırlığıyla kütlece en küçük memeliler arasındadır." },
  { id: "p05-193", k: "Doğa", s: "Çizgili sırtlan Türkiye'de en çok hangi bölgede görülür?", d: "Güneydoğu Anadolu", y: ["Doğu Karadeniz", "Trakya"], a: "Çizgili sırtlan Türkiye'de nadir bir türdür. Çoğunlukla Güneydoğu Anadolu ve Akdeniz'in doğusunda görülür." },
  { id: "p05-194", k: "Doğa", s: "Pangolinler tehlike anında kendilerini nasıl korur?", d: "Top gibi kıvrılarak", y: ["Zehir püskürterek", "Hızla koşarak"], a: "Pangolinler pullu bir top gibi kıvrılır. Sert pullar, aslan gibi büyük yırtıcıların bile onu açmasını zorlaştırır." },
  { id: "p05-195", k: "Doğa", s: "Kangurular uzun mesafelerde nasıl hareket eder?", d: "İki arka ayağıyla zıplayarak", y: ["Dört ayak üzerinde koşarak", "Ön ayaklarıyla yürüyerek"], a: "Kangurular güçlü arka bacakları ve esnek tendonlarıyla zıplar. Tendonlar yay gibi enerji depolayıp geri verir." },
  { id: "p05-196", k: "Doğa", s: "Çitaların gözünden ağzına uzanan siyah çizgilerin işlevine dair yaygın açıklama nedir?", d: "Güneş parlamasını azaltmak", y: ["Avı hipnotize etmek", "Gözyaşını boşaltmak"], a: "Bu siyah \"gözyaşı çizgileri\"nin, gündüz avlanan çitada güneş ışığının parlamasını azalttığı düşünülür." },
  { id: "p05-197", k: "Doğa", s: "Sığırlar ve atlar gibi otlayan hayvanların gözleri genellikle nerededir?", d: "Başın yanlarında", y: ["Başın tam önünde", "Başın tepesinde"], a: "Başın yanlarındaki gözler neredeyse çepeçevre görüş sağlar. Bu, av hayvanlarının yırtıcıyı erken fark etmesine yardım eder." },
  { id: "p05-198", k: "Doğa", s: "Aslan ve kaplan gibi yırtıcıların gözleri neden başın önündedir?", d: "Mesafeyi iyi ölçmek için", y: ["Arkayı görmek için", "Gözleri korumak için"], a: "Öne bakan gözlerin görüş alanları örtüşür. Bu derinlik algısını artırır ve avın uzaklığını doğru ölçmeyi sağlar." },
  { id: "p05-199", k: "Doğa", s: "Fillerin uzaktaki titreşimleri algılamak için kullandığı organ hangisidir?", d: "Ayak tabanları", y: ["Dişleri", "Kuyrukları"], a: "Fillerin ayak tabanlarındaki hassas alıcılar, uzaktaki fillerin gürlemeleriyle yerde oluşan titreşimleri algılayabilir." },
  { id: "p05-200", k: "Doğa", s: "Zürafalar ayakta doğum yaptığı için yeni doğan yavru ne yaşar?", d: "Yaklaşık iki metreden yere düşer", y: ["Annesinin sırtına konar", "Suya düşer"], a: "Zürafa anneler ayakta doğurur; yavru yaklaşık iki metre yükseklikten yere düşer. Bir saat kadar içinde ayağa kalkabilir." },
  { id: "p05-201", k: "Doğa", s: "Günümüz hayvanları arasında yalnızca kuşlarda bulunan yapı hangisidir?", d: "Tüy", y: ["Gaga", "Kanat"], a: "Gaga ornitorenkte, kanat ise yarasa ve böceklerde de vardır. Tüy ise bugün yalnızca kuşlarda bulunur." },
  { id: "p05-202", k: "Doğa", s: "Uçan kuşların birçok kemiğinin içi nasıldır?", d: "Hava boşluklarıyla doludur", y: ["Tamamen kıkırdaktır", "Sıvı yağ doludur"], a: "Uçan kuşların birçok kemiği içi boş ve destek çubuklarıyla güçlendirilmiştir. Bu yapı iskeleti hafif ama sağlam tutar." },
  { id: "p05-203", k: "Doğa", s: "Dişleri olmayan kuşlarda besini öğüten organ hangisidir?", d: "Taşlık", y: ["Kursak", "Kloak"], a: "Taşlık, kalın kaslı duvarlarıyla besini ezer. Birçok kuş öğütmeye yardım etsin diye küçük taşlar da yutar." },
  { id: "p05-204", k: "Doğa", s: "Birçok kuşun boğazındaki kursağın temel görevi nedir?", d: "Besini geçici olarak depolamak", y: ["Ses çıkarmak", "Su içmeyi engellemek"], a: "Kursak yemek borusunun genişlemiş bir bölümüdür. Kuş hızla yediği besini burada biriktirir ve yavaş yavaş sindirime gönderir." },
  { id: "p05-205", k: "Doğa", s: "Yaşayan en büyük kuş hangisidir?", d: "Devekuşu", y: ["Emu", "And kondoru"], a: "Devekuşu 2,5 metreyi aşan boyu ve 100 kilogramı aşabilen ağırlığıyla yaşayan en büyük kuştur. Uçamaz ama çok hızlı koşar." },
  { id: "p05-206", k: "Doğa", s: "Devekuşunun her ayağında kaç parmak vardır?", d: "İki", y: ["Üç", "Dört"], a: "Devekuşu, her ayağında yalnızca iki parmak bulunan tek kuştur. Bu yapı hızlı koşmasına yardım eder." },
  { id: "p05-207", k: "Doğa", s: "Devekuşları tehlike anında genellikle ne yapar?", d: "Kaçar ya da tekmeyle savunur", y: ["Başını kuma gömer", "Ölü taklidi yapar"], a: "Devekuşlarının başını kuma gömdüğü bir efsanedir. Tehlikede hızla kaçar, sıkışırsa güçlü tekmeleriyle karşılık verirler." },
  { id: "p05-208", k: "Doğa", s: "Vücut büyüklüğüne oranla en büyük yumurtayı yapan kuşlardan biri hangisidir?", d: "Kivi", y: ["Devekuşu", "Tavuk"], a: "Kivinin yumurtası annenin vücut ağırlığının yaklaşık beşte biri kadardır. Devekuşu yumurtası ise mutlak boyutça en büyüğüdür." },
  { id: "p05-209", k: "Doğa", s: "Dünyanın en küçük kuşu hangisidir?", d: "Arı sinekkuşu", y: ["Çalıkuşu", "Kanarya"], a: "Küba'da yaşayan arı sinekkuşu yaklaşık 2 gram ağırlığı ve 5-6 santimetrelik boyuyla dünyanın en küçük kuşudur." },
  { id: "p05-210", k: "Doğa", s: "Geriye doğru uçabilmesiyle bilinen kuş hangisidir?", d: "Sinekkuşu", y: ["Serçe", "Kırlangıç"], a: "Sinekkuşları kanatlarını omuzdan döndürebilir. Bu sayede havada asılı durabilir ve geriye doğru uçabilirler." },
  { id: "p05-211", k: "Doğa", s: "Sinekkuşlarının ana besini nedir?", d: "Çiçek nektarı", y: ["Tohum", "Balık"], a: "Sinekkuşları uzun dilleriyle çiçeklerden nektar emer. Protein ihtiyaçlarını küçük böcek ve örümceklerden karşılarlar." },
  { id: "p05-212", k: "Doğa", s: "Dalış sırasında ulaştığı hızla en hızlı hayvan kabul edilen kuş hangisidir?", d: "Alaca doğan", y: ["Devekuşu", "Kel kartal"], a: "Alaca doğan avına dalarken saatte 300 kilometreyi aşan hızlara ulaşabilir. Bu, hayvanlar âleminde ölçülen en yüksek hızdır." },
  { id: "p05-213", k: "Doğa", s: "Yaşayan kuşlar arasında en geniş kanat açıklığına sahip olan hangisidir?", d: "Gezgin albatros", y: ["Kel kartal", "Ak pelikan"], a: "Gezgin albatrosun kanat açıklığı 3,5 metreye ulaşabilir. Bu uzun kanatlarla okyanus üzerinde saatlerce süzülür." },
  { id: "p05-214", k: "Doğa", s: "Bilinen en uzun yıllık göçü yapan kuş hangisidir?", d: "Kutup sumru", y: ["Ak leylek", "Kırlangıç"], a: "Kutup sumruları her yıl Kuzey Kutbu çevresindeki üreme alanlarıyla Antarktika arasında gidip gelir; yıllık yolları 70 bin kilometreyi aşabilir." },
  { id: "p05-215", k: "Doğa", s: "Yaşayan en büyük penguen türü hangisidir?", d: "İmparator pengueni", y: ["Kral pengueni", "Galapagos pengueni"], a: "İmparator penguenler 1 metreyi aşan boyları ve 20-40 kilogram ağırlıklarıyla en büyük penguenlerdir." },
  { id: "p05-216", k: "Doğa", s: "İmparator penguenlerde yumurtayı Antarktika kışı boyunca kim kuluçkaya yatırır?", d: "Erkek", y: ["Dişi", "Sürünün en yaşlısı"], a: "Erkek imparator penguen yumurtayı ayaklarının üstünde, karın derisinin altında tutar. Bu süre boyunca yaklaşık iki ay hiçbir şey yemez." },
  { id: "p05-217", k: "Doğa", s: "Ekvatora en yakın yaşayan penguen türü hangisidir?", d: "Galapagos pengueni", y: ["İmparator pengueni", "Adelie pengueni"], a: "Galapagos penguenleri ekvator üzerindeki Galapagos Adaları'nda yaşar. Soğuk okyanus akıntıları burada yaşamalarını mümkün kılar." },
  { id: "p05-218", k: "Doğa", s: "Kiviyi diğer kuşlardan ayıran burun özelliği nedir?", d: "Burun delikleri gaga ucundadır", y: ["Burun deliği yoktur", "Burnu hortum gibi uzar"], a: "Kivinin burun delikleri uzun gagasının ucundadır. Gagasını toprağa sokup solucan ve böcekleri kokularından bulur." },
  { id: "p05-219", k: "Doğa", s: "Uçamayan kivi kuşu doğal olarak hangi ülkede yaşar?", d: "Yeni Zelanda", y: ["Avustralya", "Brezilya"], a: "Kivi yalnızca Yeni Zelanda'da yaşar ve ülkenin ulusal sembolüdür. Yeni Zelandalılara bu yüzden \"Kiwi\" de denir." },
  { id: "p05-220", k: "Doğa", s: "Soyu 1600'lerde tükenen uçamayan dodo kuşu nerede yaşıyordu?", d: "Mauritius adasında", y: ["Galapagos Adaları'nda", "İzlanda'da"], a: "Dodo, Hint Okyanusu'ndaki Mauritius adasında yaşıyordu. İnsanların ve getirdikleri hayvanların etkisiyle 17. yüzyılın sonlarında yok oldu." },
  { id: "p05-221", k: "Doğa", s: "Baykuşlar başlarını yaklaşık kaç derece çevirebilir?", d: "270 derece", y: ["90 derece", "360 derece"], a: "Baykuşlar boyunlarındaki fazla omur ve özel damar yapısı sayesinde başlarını yaklaşık 270 derece çevirebilir. Tam tur atamazlar." },
  { id: "p05-222", k: "Doğa", s: "Baykuşlar neden etrafa bakmak için başlarını çevirmek zorundadır?", d: "Gözleri yuvalarında hareket etmez", y: ["Tek gözleri vardır", "Gündüz kördürler"], a: "Baykuşların gözleri büyük ve tüp biçimlidir; kemik halkalarla sabitlenmiştir. Gözlerini oynatamadıkları için başlarını çevirirler." },
  { id: "p05-223", k: "Doğa", s: "Baykuşların neredeyse sessiz uçmasını sağlayan özellik nedir?", d: "Tüylerinin tarak gibi kenarları", y: ["Kanat çırpmamaları", "Rüzgârla uçmaları"], a: "Baykuşların kanat tüylerinin ön kenarında tarak benzeri çıkıntılar, yüzeyinde de yumuşak bir doku vardır. Bunlar havanın çıkardığı sesi azaltır." },
  { id: "p05-224", k: "Doğa", s: "Baykuşlar yuttukları avın kemik ve kürklerini ne yapar?", d: "Topak hâlinde ağızdan çıkarır", y: ["Tamamen sindirir", "Yuvaya taşır"], a: "Baykuşlar avlarını çoğunlukla bütün yutar. Sindiremedikleri kemik ve kürk mide de sıkıştırılıp pelet denen topaklar hâlinde kusulur." },
  { id: "p05-225", k: "Doğa", s: "Bazı baykuşların kulakları başlarının iki yanında neden farklı yüksekliktedir?", d: "Sesin yerini tam bulmak için", y: ["Rüzgârdan korunmak için", "Tüyleri düzeltmek için"], a: "Peçeli baykuş gibi türlerde asimetrik kulaklar sesin iki kulağa farklı zamanda ulaşmasını sağlar. Böylece karanlıkta avı sesinden bulurlar." },
  { id: "p05-226", k: "Doğa", s: "Papağanların ayak parmakları nasıl dizilmiştir?", d: "İkisi öne, ikisi arkaya", y: ["Dördü de öne", "Üçü arkaya, biri öne"], a: "Papağanların iki parmağı öne, iki parmağı arkaya bakar. Bu düzen dallara tutunmayı ve yiyeceği ayakla tutmayı kolaylaştırır." },
  { id: "p05-227", k: "Doğa", s: "Ağaçkakanlar ağaçları gagalayarak ne yapar?", d: "Böcek arar ve yuva oyar", y: ["Ağaç özsuyunu temizler", "Gagasını kısaltır"], a: "Ağaçkakanlar gagalarıyla ağaçtaki böcek larvalarına ulaşır ve yuva oyar. Hızlı vuruşlarla \"davul\" çalıp bölgelerini de duyururlar." },
  { id: "p05-228", k: "Doğa", s: "Ağaçkakanın uzun dili kullanılmadığında nerede durur?", d: "Kafatasının etrafına sarılır", y: ["Midesinde", "Gagasının dışında"], a: "Birçok ağaçkakanın dilini taşıyan uzun dil kemiği kafatasının arkasından dolanır. Bu sayede dilini çok uzağa uzatabilir." },
  { id: "p05-229", k: "Doğa", s: "Flamingoların pembe rengi nereden gelir?", d: "Yedikleri besinlerdeki pigmentlerden", y: ["Kanlarının derilerinden görünmesinden", "Güneş yanığından"], a: "Flamingolar karotenoid pigmentleri içeren alg ve küçük kabukluları yer. Bu pigmentler tüylerini pembeye boyar." },
  { id: "p05-230", k: "Doğa", s: "Flamingolar nasıl beslenir?", d: "Başları ters dönük, suyu süzerek", y: ["Balığa dalarak", "Ağaçlardan meyve toplayarak"], a: "Flamingolar başlarını suya ters çevirir ve gagalarındaki süzgeç benzeri yapılarla sudaki küçük canlıları süzer." },
  { id: "p05-231", k: "Doğa", s: "Pelikanın gagasının altındaki büyük kese ne işe yarar?", d: "Balığı suyla birlikte kepçelemeye", y: ["Balıkları günlerce saklamaya", "Ses yükseltmeye"], a: "Pelikanlar kesesiyle balığı suyla birlikte kepçeler. Sonra suyu boşaltıp balığı yutar; kese bir depo değildir." },
  { id: "p05-232", k: "Doğa", s: "Birçok guguk kuşu türü yavrularını nasıl büyütür?", d: "Yumurtalarını başka kuşların yuvasına bırakır", y: ["Yavrularını sırtında taşır", "Yuvayı toprağa kazar"], a: "Guguk kuşları yumurtalarını başka türlerin yuvalarına bırakır. Yavruyu farkında olmadan o kuşlar büyütür; buna kuluçka parazitliği denir." },
  { id: "p05-233", k: "Doğa", s: "Göçmen kuşlar yönlerini bulmak için hangisinden yararlanır?", d: "Dünya'nın manyetik alanından", y: ["Ay'ın çekiminden", "Okyanus tuzluluğundan"], a: "Göçmen kuşlar yön bulmak için Güneş'ten, yıldızlardan, yer şekillerinden ve Dünya'nın manyetik alanından yararlanır." },
  { id: "p05-234", k: "Doğa", s: "Ak leylekler göçte neden İstanbul Boğazı gibi dar deniz geçişlerini tercih eder?", d: "Süzülmek için karadaki sıcak hava akımlarına ihtiyaç duyar", y: ["Boğazda balık avlar", "Denizi göremez"], a: "Leylekler yükselen sıcak hava akımlarıyla süzülerek enerji tasarruf eder. Bu akımlar denizde zayıf olduğundan en kısa deniz geçişini seçerler." },
  { id: "p05-235", k: "Doğa", s: "Neredeyse sessiz olan ak leylekler birbiriyle nasıl iletişim kurar?", d: "Gagalarını takırdatarak", y: ["Şarkı söyleyerek", "Kanatlarını çırparak ıslık çalarak"], a: "Ak leyleklerin ötme yeteneği çok sınırlıdır. Yuvada başlarını geriye atıp gagalarını hızla takırdatarak iletişim kurarlar." },
  { id: "p05-236", k: "Doğa", s: "Siyah kuğunun anavatanı neresidir?", d: "Avustralya", y: ["Kanada", "Norveç"], a: "Siyah kuğular Avustralya'ya özgüdür. Avrupalılar onları görene kadar \"siyah kuğu\" olmayacak bir şeyin simgesiydi." },
  { id: "p05-237", k: "Doğa", s: "Amerika Birleşik Devletleri'nin ulusal kuşu hangisidir?", d: "Kel kartal", y: ["Hindi", "Alaca doğan"], a: "Kel kartal 1782'de ABD'nin büyük mührüne konmuştur. Adına rağmen kel değildir; başı beyaz tüylerle kaplıdır." },
  { id: "p05-238", k: "Doğa", s: "Birçok akbabanın başının tüysüz olmasının yaygın açıklaması nedir?", d: "Leş yerken temiz kalmak", y: ["Daha hızlı uçmak", "Eş bulmak"], a: "Akbabalar başlarını leşin içine sokar. Tüysüz baş daha kolay temiz kalır; vücut ısısını düzenlemeye de yardım ettiği düşünülür." },
  { id: "p05-239", k: "Doğa", s: "Dallardan ve yapraklardan kanca biçimli aletler yapabilen kuş hangisidir?", d: "Yeni Kaledonya kargası", y: ["Saka kuşu", "Ev serçesi"], a: "Yeni Kaledonya kargaları dal ve yaprakları biçimlendirerek aletler yapar ve bunlarla ağaç kovuklarındaki larvaları çıkarır." },
  { id: "p05-240", k: "Doğa", s: "Ayna testinde kendini tanıdığı gösterilen ilk kuş hangisidir?", d: "Saksağan", y: ["Tavuk", "Güvercin"], a: "2008'deki bir çalışmada saksağanlar, aynada gördükleri ve kendi bakamadıkları yerdeki işareti temizlemeye çalıştı." },
  { id: "p05-241", k: "Doğa", s: "Güvercinler yavrularını ilk günlerde neyle besler?", d: "Kursak sütüyle", y: ["Tohum yağıyla", "Böcek larvasıyla"], a: "Güvercinlerde hem anne hem baba kursaklarında besleyici bir salgı üretir. Yavrular ilk günlerde bu \"kursak sütü\"yle beslenir." },
  { id: "p05-242", k: "Doğa", s: "Posta güvercinlerinin mesaj taşımakta kullanılmasını sağlayan yetenek nedir?", d: "Uzaktan yuvalarına dönebilmeleri", y: ["Konuşma taklit edebilmeleri", "Çok hızlı dalış yapmaları"], a: "Güvercinler yüzlerce kilometre uzağa götürülseler bile yuvalarına geri dönebilir. Bu yüzden asırlarca haberci olarak kullanıldılar." },
  { id: "p05-243", k: "Doğa", s: "Tavukların yumurtlaması için horoz gerekli midir?", d: "Hayır, yalnız civciv için gerekir", y: ["Evet, her yumurta için", "Yalnızca kışın gerekir"], a: "Tavuklar horoz olmadan da yumurtlar. Bu yumurtalar döllenmemiştir; içinden civciv çıkması için horoz gerekir." },
  { id: "p05-244", k: "Doğa", s: "Evcil tavuğun yabani atası hangisidir?", d: "Kırmızı orman tavuğu", y: ["Sülün", "Keklik"], a: "Evcil tavuklar, Güney ve Güneydoğu Asya ormanlarında yaşayan kırmızı orman tavuğundan evcilleştirilmiştir." },
  { id: "p05-245", k: "Doğa", s: "Hindinin anavatanı neresidir?", d: "Kuzey Amerika", y: ["Türkiye", "Hindistan"], a: "Adı Türkçe ve İngilizcede farklı ülkelere gönderme yapsa da hindi, Kuzey Amerika kökenlidir. Avrupa'ya 16. yüzyılda geldi." },
  { id: "p05-246", k: "Doğa", s: "Kazlar ve diğer büyük göçmen kuşlar neden V düzeninde uçar?", d: "Enerji tasarrufu için", y: ["Yırtıcıları korkutmak için", "Yolu Güneş'ten bulmak için"], a: "Öndeki kuşun kanat ucunda oluşan yukarı hava akımı arkadakileri hafifçe kaldırır. Böylece sürü daha az enerji harcar." },
  { id: "p05-247", k: "Doğa", s: "Kırlangıçlar yuvalarını çoğunlukla hangi malzemeyle yapar?", d: "Çamur", y: ["Taş", "Örümcek ağı"], a: "Kırlangıçlar gagalarıyla taşıdıkları çamur topaklarını otla karıştırıp duvar ve saçak altlarına yapıştırarak yuva yapar." },
  { id: "p05-248", k: "Doğa", s: "Üreme dönemi dışında aylarca yere konmadan havada kalabilen kuş hangisidir?", d: "Kara sağan (ebabil)", y: ["Ak leylek", "Martı"], a: "Bir çalışmada kara sağanların Afrika'daki kışlama döneminde yaklaşık 10 ay boyunca neredeyse hiç konmadan uçtuğu görüldü." },
  { id: "p05-249", k: "Doğa", s: "Erkek çardak kuşları dişileri etkilemek için ne yapar?", d: "Süslü bir çardak kurar", y: ["Ağaçları kökünden söker", "Rengini değiştirir"], a: "Erkek çardak kuşları dallardan bir yapı kurar ve önünü renkli taş, tüy, çiçek gibi nesnelerle süsler. Dişiler en etkileyiciyi seçer." },
  { id: "p05-250", k: "Doğa", s: "Gösterişli tüyleri ve kur danslarıyla ünlü cennet kuşları esas olarak nerede yaşar?", d: "Yeni Gine", y: ["İskandinavya", "Sahra"], a: "Cennet kuşlarının çoğu Yeni Gine ve çevresindeki adalarda yaşar. Erkekler renkli tüyleri ve karmaşık danslarıyla dişilere kur yapar." },
  { id: "p05-251", k: "Doğa", s: "Erkek tavus kuşunun yelpaze gibi açtığı uzun tüyler aslında nedir?", d: "Kuyruğu örten üst tüyler", y: ["Gerçek kuyruk tüyleri", "Kanat tüyleri"], a: "Tavus kuşunun gösterişli \"kuyruğu\" aslında kuyruk üstü örtü tüyleridir. Gerçek kuyruk tüyleri daha kısadır ve onları arkadan destekler." },
  { id: "p05-252", k: "Doğa", s: "Tavus kuşlarında gösterişli göz desenli uzun tüyler hangi bireylerdedir?", d: "Erkeklerde", y: ["Dişilerde", "Yalnızca yavrularda"], a: "Gösterişli tüyler erkek tavus kuşlarındadır. Dişiler daha sade renklidir ve eş seçerken erkeklerin gösterilerini değerlendirir." },
  { id: "p05-253", k: "Doğa", s: "Başka kuşların seslerini ve hatta makine seslerini taklit etmesiyle ünlü Avustralya kuşu hangisidir?", d: "Lirkuşu", y: ["Emu", "Kazuar"], a: "Lirkuşları başka kuşların ötüşlerini ve fotoğraf makinesi deklanşörü gibi sesleri şaşırtıcı bir doğrulukla taklit edebilir." },
  { id: "p05-254", k: "Doğa", s: "Kuşlarda ötüşü sağlayan ses organının adı nedir?", d: "Siringe", y: ["Gırtlak kapağı", "Hava kesesi"], a: "Kuşların ses organı siringe, soluk borusunun akciğerlere ayrıldığı yerdedir. Bazı kuşlar onunla aynı anda iki farklı ses çıkarabilir." },
  { id: "p05-255", k: "Doğa", s: "Ötücü kuş yavruları türlerine özgü şarkıyı nasıl kazanır?", d: "Yetişkinleri dinleyerek öğrenir", y: ["Yumurtadan tam bilerek çıkar", "Hiç öğrenmez, rastgele öter"], a: "Ötücü kuş yavruları yetişkinleri dinleyip deneme yaparak şarkılarını geliştirir. Bu, insanların konuşmayı öğrenmesine benzetilir." },
  { id: "p05-256", k: "Doğa", s: "Hindi akbabası ormanlık alanlarda leşi nasıl bulur?", d: "Kokusundan", y: ["Ekolokasyonla", "Isısından"], a: "Hindi akbabasının koku alma duyusu kuşlar arasında çok gelişmiştir. Ağaçlar altındaki leşi kokusundan bulabilir." },
  { id: "p05-257", k: "Doğa", s: "Birçok kuş insanların göremediği hangi ışığı görebilir?", d: "Morötesi ışık", y: ["Kızılötesi ışık", "Röntgen ışınları"], a: "Birçok kuşun gözünde morötesini algılayan renk hücreleri vardır. Bu sayede tüylerde ve meyvelerde bizim göremediğimiz desenleri görürler." },
  { id: "p05-258", k: "Doğa", s: "Emularda yumurtaları kuluçkaya kim yatırır?", d: "Erkek", y: ["Dişi", "Anne ve baba sırayla"], a: "Dişi emu yumurtladıktan sonra ayrılır. Erkek yaklaşık sekiz hafta yumurtaların üstünde oturur ve bu sürede neredeyse hiç yemez." },
  { id: "p05-259", k: "Doğa", s: "Başındaki boynuzsu \"kaskla\" tanınan uçamayan kuş hangisidir?", d: "Kazuar", y: ["Devekuşu", "Rea"], a: "Yeni Gine ve Kuzey Avustralya ormanlarında yaşayan kazuarın başında kask denen bir çıkıntı vardır. Ayaklarındaki pençeler çok tehlikelidir." },
  { id: "p05-260", k: "Doğa", s: "Rea adlı uçamayan büyük kuş hangi kıtada yaşar?", d: "Güney Amerika", y: ["Afrika", "Avustralya"], a: "Rea, Güney Amerika'nın otlak ve çalılık bölgelerinde yaşar. Devekuşuna benzer ama daha küçüktür." },
  { id: "p05-261", k: "Doğa", s: "Bir çalışmaya göre tukanların kocaman gagası hangi işe yarar?", d: "Vücut ısısını dağıtmaya", y: ["Kazı yapmaya", "Yüzmeye"], a: "2009'daki bir çalışma, tukanların gagasına giden kan akışını ayarlayarak fazla ısıyı dışarı verdiğini gösterdi." },
  { id: "p05-262", k: "Doğa", s: "Japonya'daki Shinkansen hızlı treninin burnu hangi kuşun gagasından esinlenerek tasarlanmıştır?", d: "Yalıçapkını", y: ["Sinekkuşu", "Pelikan"], a: "Yalıçapkını suya neredeyse sıçratmadan dalar. Mühendisler tünel çıkışlarındaki gürültüyü azaltmak için bu gaganın şeklini örnek aldı." },
  { id: "p05-263", k: "Doğa", s: "Martı ve albatros gibi deniz kuşları içtikleri tuzlu suyun tuzunu nasıl atar?", d: "Gözlerinin üstündeki tuz bezleriyle", y: ["Terleyerek", "Tüyleriyle süzerek"], a: "Deniz kuşlarının gözlerinin üstünde tuz bezleri vardır. Fazla tuz bu bezlerden süzülür ve burun deliklerinden damlar." },
  { id: "p05-264", k: "Doğa", s: "Albatroslar okyanus üzerinde binlerce kilometreyi nasıl az enerjiyle uçar?", d: "Rüzgârdan yararlanarak süzülür", y: ["Sürekli kanat çırpar", "Dalgaların üstünde yüzer"], a: "Albatroslar dalgaların üstündeki rüzgâr farklarını kullanarak süzülür. Bu sayede saatlerce neredeyse hiç kanat çırpmadan uçabilirler." },
  { id: "p05-265", k: "Doğa", s: "Deniz papağanları (pufin) gagalarıyla ne yapabilmesiyle ünlüdür?", d: "Aynı anda çok sayıda balık taşımak", y: ["Taş kırmak", "Ağaç oymak"], a: "Deniz papağanları dilleri ve gagalarındaki çıkıntılar sayesinde yakaladıkları balıkları tutarken yeni balıklar da yakalayabilir." },
  { id: "p05-266", k: "Doğa", s: "Bilim insanlarına göre kuşlar hangi hayvan grubundan evrimleşmiştir?", d: "Dinozorlar", y: ["Yarasalar", "Kurbağalar"], a: "Kuşlar, theropod denen iki ayaklı etçil dinozorlardan evrimleşmiştir. Bu yüzden kuşlar yaşayan dinozorlar olarak da görülür." },
  { id: "p05-267", k: "Doğa", s: "Hem tüyü hem de dişli çenesi olan ünlü 150 milyon yıllık fosil hangisidir?", d: "Arkeopteriks", y: ["Tiranozor", "Pterodaktil"], a: "Almanya'da bulunan arkeopteriks, tüylü kanatlarıyla kuşlara, dişleri ve kemikli kuyruğuyla dinozorlara benzer." },
  { id: "p05-268", k: "Doğa", s: "Ter bezleri olmayan kuşlar sıcakta nasıl serinler?", d: "Gagalarını açıp hızlı soluyarak", y: ["Tüylerinden terleyerek", "Kış uykusuna yatarak"], a: "Kuşların ter bezi yoktur. Sıcakta gagalarını açar, hızlı solur ve boğazlarını titreştirerek nemi buharlaştırırlar." },
  { id: "p05-269", k: "Doğa", s: "Kuluçkadaki kuşun yumurtayı ısıtmak için göğsünde açılan tüysüz bölgeye ne denir?", d: "Kuluçka lekesi", y: ["Kursak", "Taşlık"], a: "Kuluçka döneminde birçok kuşun göğsünde tüyleri dökülen ve damarlanan bir bölge oluşur. Bu çıplak deri yumurtaları doğrudan ısıtır." },
  { id: "p05-270", k: "Doğa", s: "Çalı tavukları (megapodlar) yumurtalarını nasıl ısıtır?", d: "Çürüyen bitkilerden höyük yaparak", y: ["Üzerinde oturarak", "Güneşte taş üstüne bırakarak"], a: "Megapodlar yumurtalarını yaprak ve topraktan yaptıkları höyüklere gömer. Çürüyen bitkilerin çıkardığı ısı yumurtaları ısıtır." },
  { id: "p05-271", k: "Doğa", s: "Tavuk yumurtasından civcivin çıkması yaklaşık ne kadar sürer?", d: "21 gün", y: ["7 gün", "45 gün"], a: "Döllenmiş tavuk yumurtası yaklaşık 37-38 °C'de 21 gün kuluçkada kaldıktan sonra civciv yumurtadan çıkar." },
  { id: "p05-272", k: "Doğa", s: "Konrad Lorenz'in kazlarla yaptığı ünlü çalışmalar hangi davranışı gösterdi?", d: "Yavruların ilk gördüğünü izlemesi", y: ["Kazların göç yolunu ezberlemesi", "Kazların sayı sayması"], a: "Lorenz, yumurtadan yeni çıkan kaz yavrularının ilk gördükleri hareketli varlığa bağlanıp onu izlediğini gösterdi. Buna damgalanma denir." },
  { id: "p05-273", k: "Doğa", s: "Hoatzin kuşunun yavruları ağaçta tırmanmak için neyi kullanır?", d: "Kanatlarındaki pençeleri", y: ["Kuyruklarını", "Gagalarındaki dişleri"], a: "Güney Amerika'da yaşayan hoatzin yavrularının kanatlarında iki pençe bulunur. Bu pençeler büyüdükçe kaybolur." },
  { id: "p05-274", k: "Doğa", s: "Uçamayan, gece aktif ve dünyanın en ağır papağanı olan kuş hangisidir?", d: "Kakapo", y: ["Ara papağanı", "Kakadu"], a: "Yeni Zelanda'ya özgü kakapo uçamaz, gece aktiftir ve 4 kilograma kadar çıkabilir. Nesli kritik derecede tehlikededir." },
  { id: "p05-275", k: "Doğa", s: "Karanlık mağaralarda ekolokasyonla yolunu bulabilen kuş hangisidir?", d: "Yağ kuşu", y: ["Puhu", "Kızılgerdan"], a: "Güney Amerika'daki yağ kuşları mağaralarda insanın da duyabileceği tıklama sesleri çıkarır ve yankılarıyla yollarını bulur." },
  { id: "p05-276", k: "Doğa", s: "Bazı salanganlar (mağara ebabilleri) yuvalarını esas olarak neyden yapar?", d: "Kendi tükürüklerinden", y: ["Kuru otlardan", "Çamurdan"], a: "Bazı salangan türleri yuvalarını sertleşen tükürüklerinden yapar. Bu yuvalar Asya'da yiyecek olarak toplanır." },
  { id: "p05-277", k: "Doğa", s: "Güney Afrika'da yüzlerce kuşun birlikte yaşadığı dev ortak yuvalar yapan kuş hangisidir?", d: "Sosyal dokumacı kuş", y: ["Ak leylek", "Saksağan"], a: "Sosyal dokumacı kuşlar ağaçlara kuru otlardan dev bir yapı örer. İçinde her çiftin ayrı odası bulunur." },
  { id: "p05-278", k: "Doğa", s: "Uçan kuşlarda güçlü uçuş kaslarının tutunduğu göğüs kemiği çıkıntısına ne denir?", d: "Karina", y: ["Kursak", "Siringe"], a: "Uçan kuşların göğüs kemiğinde gemi omurgasına benzeyen karina denen bir çıkıntı vardır. Büyük göğüs kasları buraya tutunur." },
  { id: "p05-279", k: "Doğa", s: "Devekuşu, emu ve kivi gibi uçamayan kuşların göğüs kemiği nasıldır?", d: "Düzdür, karinası yoktur", y: ["Uçan kuşlardan daha çıkıntılıdır", "Hiç göğüs kemiği yoktur"], a: "Bu uçamayan kuşlara ratitler denir. Göğüs kemikleri sal gibi düzdür; büyük uçuş kaslarına ihtiyaç duymazlar." },
  { id: "p05-280", k: "Doğa", s: "Arı kuşları yakaladıkları arıları yemeden önce ne yapar?", d: "Dala sürterek iğnesini çıkarır", y: ["Suya batırır", "Yuvaya gömer"], a: "Arı kuşu arıyı dala vurup sürter. Böylece iğneyi ve zehrin çoğunu çıkardıktan sonra yutar." },
  { id: "p05-281", k: "Doğa", s: "Muhabbet kuşlarının anavatanı neresidir?", d: "Avustralya", y: ["Hindistan", "Brezilya"], a: "Muhabbet kuşları Avustralya'nın kurak iç bölgelerinde büyük sürüler hâlinde yaşar. Doğadaki bireyler genellikle yeşil-sarıdır." },
  { id: "p05-282", k: "Doğa", s: "Kömür madenlerinde kanaryalar neden kullanılırdı?", d: "Zehirli gazları erken fark etmek için", y: ["Madencileri eğlendirmek için", "Fareleri kovmak için"], a: "Kanaryalar karbon monoksit gibi gazlardan insandan önce etkilenir. Kuşun rahatsızlanması madencilere kaçmaları için uyarı olurdu." },
  { id: "p05-283", k: "Doğa", s: "Kuş dışkısındaki beyaz kısım nedir?", d: "Ürik asit", y: ["Kalsiyum taşı", "Sindirilmemiş tüy"], a: "Kuşlar azotlu atıklarını su kaybını azaltan ürik asit olarak atar. Dışkıdaki beyaz kısım budur; idrar ayrı atılmaz." },
  { id: "p05-284", k: "Doğa", s: "Kuşlarda dışkı, idrar ve yumurtanın çıktığı ortak açıklığa ne denir?", d: "Kloak", y: ["Kursak", "Taşlık"], a: "Kuşlarda sindirim, boşaltım ve üreme kanalları kloak denen tek bir açıklıkta birleşir." },
  { id: "p05-285", k: "Doğa", s: "Kuş yumurtasının kabuğu esas olarak hangi maddeden oluşur?", d: "Kalsiyum karbonat", y: ["Keratin", "Silika"], a: "Yumurta kabuğu büyük ölçüde kalsiyum karbonattır. Üzerindeki binlerce küçük gözenek, embriyonun hava almasını sağlar." },
  { id: "p05-286", k: "Doğa", s: "Kuşların vücut sıcaklığı insanınkine göre genellikle nasıldır?", d: "Daha yüksektir", y: ["Daha düşüktür", "Çevreyle aynıdır"], a: "Kuşların vücut sıcaklığı çoğunlukla 40-42 °C arasındadır. Bu, insanın yaklaşık 37 °C'lik sıcaklığından yüksektir." },
  { id: "p05-287", k: "Doğa", s: "Kuş tüyleri hangi proteinden yapılmıştır?", d: "Keratin", y: ["Kolajen", "Hemoglobin"], a: "Kuş tüyleri, saçımız ve tırnaklarımızdaki gibi keratinden oluşur. Tüy, sürüngen pullarıyla akraba bir yapıdır." },
  { id: "p05-288", k: "Doğa", s: "Kuşların yıpranan tüylerini düzenli olarak dökerek yenilemesine ne denir?", d: "Tüy değiştirme", y: ["Kuluçka", "Damgalanma"], a: "Tüyler zamanla aşınır. Kuşlar genellikle yılda bir ya da iki kez tüy değiştirerek eski tüylerin yerine yenilerini çıkarır." },
  { id: "p05-289", k: "Doğa", s: "Birçok kuş tüylerini düzeltirken hangi salgıyı sürer?", d: "Kuyruk dibindeki bezin yağını", y: ["Tükürüğünü", "Göz yaşını"], a: "Birçok kuşun kuyruk sokumunda bir yağ bezi bulunur. Kuş bu yağı gagasıyla tüylerine sürerek onları bakımlı ve suya dayanıklı tutar." },
  { id: "p05-290", k: "Doğa", s: "Kartallar uzaktaki küçük bir avı neden çok iyi görür?", d: "Retinalarında görme hücreleri çok yoğundur", y: ["Gözleri ışık saçar", "Ekolokasyon kullanırlar"], a: "Kartalların retinasında insandan çok daha yoğun görme hücreleri bulunur. Bu, çok uzaktaki ayrıntıları görmelerini sağlar." },
  { id: "p05-291", k: "Doğa", s: "Penguenlerin sırtının siyah, karnının beyaz olması ne işe yarar?", d: "Suda kamuflaj sağlar", y: ["Eş seçimini kolaylaştırır", "Buzu eritir"], a: "Yukarıdan bakan bir yırtıcı siyah sırtı karanlık suyla, aşağıdan bakan beyaz karnı aydınlık yüzeyle karıştırır." },
  { id: "p05-292", k: "Doğa", s: "Penguenler su altında kanatlarını nasıl kullanır?", d: "Yüzgeç gibi çırparak", y: ["Katlayıp hiç kullanmaz", "Yelken gibi açarak"], a: "Penguenlerin kanatları kısa, sert ve yassıdır. Su altında bunları çırparak adeta suda \"uçarlar\"." },
  { id: "p05-293", k: "Doğa", s: "İmparator penguenler Antarktika kışının dondurucu fırtınalarına nasıl dayanır?", d: "Sıkışık kümeler oluşturarak", y: ["Toprağa yuva kazarak", "Kuzeye göç ederek"], a: "İmparator penguenler binlercesi bir arada sıkışık kümeler oluşturur. Sırayla kümenin ortasına ve kenarına geçerek ısıyı paylaşırlar." },
  { id: "p05-294", k: "Doğa", s: "Güvercinlerin yürürken başını ileri geri sallamasının sebebi nedir?", d: "Görüntüyü sabit tutmak", y: ["Denge sağlamak", "Eşine işaret vermek"], a: "Güvercin başını bir an sabit tutar, sonra hızla öne atar. Baş sabitken çevresini net görür; bu, hareketi algılamasını kolaylaştırır." },
  { id: "p05-295", k: "Doğa", s: "Göçmen kuşlar uzun yolculuğa çıkmadan önce ne yapar?", d: "Bol yiyip yağ depolar", y: ["Tüylerini tamamen döker", "Kış uykusuna yatar"], a: "Göçten önce birçok kuş çok yemek yer ve vücudunda yağ biriktirir. Bu yağ, yolculuk boyunca yakıt görevi görür." },
  { id: "p05-296", k: "Doğa", s: "Alaska'dan Yeni Zelanda'ya hiç konmadan uçabildiği kaydedilen kuş hangisidir?", d: "Kıyı çamurçulluğu", y: ["Ak pelikan", "Kızılgerdan"], a: "Uydu vericili kıyı çamurçullukları Alaska'dan Yeni Zelanda'ya 11 bin kilometreyi aşan yolu durmadan uçtu. Bu bilinen en uzun kesintisiz kuş uçuşları arasındadır." },
  { id: "p05-297", k: "Doğa", s: "Binlerce bireyle gökyüzünde dalgalanan şekiller oluşturmasıyla ünlü kuş hangisidir?", d: "Sığırcık", y: ["Kartal", "Baykuş"], a: "Sığırcık sürülerinde her kuş yakınındaki birkaç komşusunun hareketini izler. Bu basit kural, büyüleyici dalgalı desenler oluşturur." },
  { id: "p05-298", k: "Doğa", s: "Tavuk ve ördek yavruları yumurtadan çıktığında nasıldır?", d: "Tüylüdür ve kısa sürede yürür", y: ["Çıplak ve kördür", "Hemen uçabilir"], a: "Tavuk ve ördek yavruları tüylü, gözleri açık doğar ve kısa sürede yürüyüp beslenebilir. Serçe gibi ötücü kuşların yavruları ise çıplak ve kör çıkar." },
  { id: "p05-299", k: "Doğa", s: "Kuşlarda akciğerlere ek olarak solunuma yardım eden yapılar nelerdir?", d: "Hava keseleri", y: ["Solungaçlar", "Deri gözenekleri"], a: "Kuşların akciğerlerine bağlı hava keseleri, havanın akciğerlerden tek yönde akmasını sağlar. Bu, uçuşun gerektirdiği bol oksijeni karşılar." },
  { id: "p05-300", k: "Doğa", s: "Kuşların kalbi kaç odacıklıdır?", d: "Dört", y: ["İki", "Üç"], a: "Kuşlar da memeliler gibi dört odacıklı kalbe sahiptir. Uçmanın gerektirdiği yüksek enerjiyi karşılamak için kalpleri hızlı atar." },
];
